files.shaders/city.gdshader:
shader_type spatial;
// Night skyscrapers with random lit windows. Per-instance COLOR: rgb = accent, a = seed.

uniform float lit_amount = 0.45;
uniform float win_energy = 1.8;

varying vec3 wp;
varying vec3 wn;
varying vec4 ic;

float h2(vec2 p) {
	return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void vertex() {
	wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	wn = normalize((MODEL_MATRIX * vec4(NORMAL, 0.0)).xyz);
	ic = COLOR;
}

void fragment() {
	float side = 1.0 - step(0.8, abs(wn.y));
	float u = abs(wn.x) > 0.5 ? wp.z : wp.x;
	vec2 cp = vec2(u * 1.25, wp.y * 0.95);
	vec2 f = fract(cp);
	float win = step(0.2, f.x) * step(f.x, 0.8) * step(0.28, f.y) * step(f.y, 0.78);
	float h = h2(floor(cp) + ic.a * 91.7 + floor(wn.xz * 3.0));
	float lit = step(1.0 - lit_amount, h) * win * side;
	vec3 warm = vec3(1.0, 0.72, 0.38);
	vec3 wc = mix(warm, ic.rgb, step(0.82, h));
	ALBEDO = vec3(0.035, 0.035, 0.06) + ic.rgb * 0.02;
	METALLIC = 0.6;
	ROUGHNESS = 0.3;
	EMISSION = wc * lit * win_energy * (0.6 + 0.4 * h);
}

files.shaders/grid.gdshader:
shader_type spatial;

uniform vec4 base : source_color = vec4(0.025, 0.02, 0.05, 1.0);
uniform vec4 line : source_color = vec4(0.0, 0.9, 1.0, 1.0);
uniform float cell = 2.0;
uniform float width = 0.03;
uniform float energy = 2.5;
uniform float fade = 60.0;
uniform vec2 scroll = vec2(0.0);
uniform float metal = 0.7;
uniform float rough = 0.22;

varying vec3 wpos;

void vertex() {
	wpos = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
}

void fragment() {
	vec2 p = wpos.xz / cell + scroll * TIME;
	vec2 d = abs(fract(p - 0.5) - 0.5);
	vec2 fw = fwidth(p);
	vec2 a = 1.0 - smoothstep(vec2(width), vec2(width) + fw * 1.5, d);
	float g = max(a.x, a.y);
	float dist = length(wpos.xz - CAMERA_POSITION_WORLD.xz);
	g *= 1.0 - smoothstep(fade * 0.35, fade, dist);
	ALBEDO = base.rgb;
	METALLIC = metal;
	ROUGHNESS = rough;
	EMISSION = line.rgb * g * energy;
}

files.shaders/sky.gdshader:
shader_type sky;

uniform vec3 top_col : source_color = vec3(0.02, 0.01, 0.06);
uniform vec3 hor_col : source_color = vec3(0.25, 0.06, 0.4);
uniform vec3 bot_col : source_color = vec3(0.03, 0.02, 0.06);
uniform float stars = 1.0;
uniform vec3 sun_dir = vec3(0.3, 0.2, -1.0);
uniform vec3 sun_col : source_color = vec3(1.0, 0.6, 0.3);
uniform float sun_size = 0.0;
uniform float band = 0.6;
uniform vec3 neb_col : source_color = vec3(0.4, 0.05, 0.5);
uniform float nebula = 0.0;

float hash3(vec3 p) {
	return fract(sin(dot(p, vec3(12.9898, 78.233, 37.719))) * 43758.5453);
}

float vnoise(vec3 p) {
	vec3 i = floor(p);
	vec3 f = fract(p);
	f = f * f * (3.0 - 2.0 * f);
	float a = mix(mix(hash3(i), hash3(i + vec3(1, 0, 0)), f.x), mix(hash3(i + vec3(0, 1, 0)), hash3(i + vec3(1, 1, 0)), f.x), f.y);
	float b = mix(mix(hash3(i + vec3(0, 0, 1)), hash3(i + vec3(1, 0, 1)), f.x), mix(hash3(i + vec3(0, 1, 1)), hash3(i + vec3(1, 1, 1)), f.x), f.y);
	return mix(a, b, f.z);
}

void sky() {
	vec3 d = EYEDIR;
	float h = d.y;
	vec3 c = mix(hor_col, top_col, pow(clamp(h, 0.0, 1.0), 0.55));
	c = mix(c, bot_col, smoothstep(0.0, -0.18, h));
	c += hor_col * band * exp(-abs(h) * 16.0);
	if (nebula > 0.0) {
		float n = vnoise(d * 3.0) * 0.6 + vnoise(d * 7.0) * 0.4;
		c += neb_col * smoothstep(0.45, 0.9, n) * nebula * smoothstep(-0.05, 0.3, h);
	}
	if (stars > 0.0 && h > -0.02 && !AT_CUBEMAP_PASS) {
		vec3 p = d * 260.0;
		vec3 cell = floor(p);
		float r = hash3(cell);
		vec3 sp = cell + 0.5 + (vec3(hash3(cell + 1.7), hash3(cell + 3.1), hash3(cell + 5.3)) - 0.5) * 0.6;
		float dd = length(p - sp);
		float s = step(0.993, r) * smoothstep(0.55, 0.0, dd) * smoothstep(-0.02, 0.25, h);
		c += vec3(s * stars * (0.6 + 2.0 * fract(r * 91.0)));
	}
	if (sun_size > 0.0) {
		float sd = dot(d, normalize(sun_dir));
		c += sun_col * smoothstep(1.0 - sun_size, 1.0 - sun_size * 0.6, sd) * 1.6;
		c += sun_col * pow(max(sd, 0.0), 24.0) * 0.35;
	}
	COLOR = c;
}

files.shaders/wipe.gdshader:
shader_type canvas_item;
uniform float r = 2.0;
uniform vec2 size = vec2(1200.0, 900.0);

void fragment() {
	vec2 p = UV * size;
	// diagonal slash wipe with neon edge
	float d = (p.x + p.y * 0.6) / (size.x + size.y * 0.6);
	float edge = r * 1.3 - 0.15;
	float inside = step(d, edge);
	float stripes = step(0.5, fract((p.x - p.y) / 18.0));
	vec3 fill = mix(vec3(0.027, 0.024, 0.06), vec3(0.05, 0.04, 0.1), stripes);
	float rim = smoothstep(0.03, 0.0, abs(d - edge));
	vec3 col = mix(fill, vec3(0.0, 0.9, 1.0), rim);
	COLOR = vec4(col, max(inside, rim) * step(0.001, r) * step(r, 1.2));
}

files.scripts/g.gd:
extends Node
## Globals: neon palette, fonts, audio, save data/XP ranks and HUD drawing helpers.

const INK := Color("07060f")
const PANEL := Color(0.05, 0.04, 0.1, 0.84)
const CYAN := Color("00e5ff")
const MAGENTA := Color("ff2bd6")
const LIME := Color("a6ff00")
const ORANGE := Color("ff7a1a")
const YELLOW := Color("ffd60a")
const RED := Color("ff2e4d")
const PURPLE := Color("8b5cf6")
const WHITE := Color("ffffff")
const STEEL := Color("8a90a8")
const NEON := [Color("00e5ff"), Color("ff2bd6"), Color("a6ff00"), Color("ff7a1a"), Color("ffd60a"), Color("8b5cf6")]

const SFX := ["beep", "boom", "boom_s", "boss", "charge", "cheer", "clank", "click", "crunch", "fanfare", "jump", "kick",
	"laser", "laser2", "lose", "rocket", "select", "shatter", "snip", "speedup", "thud", "tick", "tock", "tone0", "tone1",
	"tone2", "tone3", "whoosh", "win", "xp", "zap"]

const RANKS := [[0, "ROOKIE"], [200, "CHALLENGER"], [600, "PRO"], [1500, "ELITE"], [3000, "MASTER"], [6000, "LEGEND"], [12000, "MYTHIC"]]

var font_title: Font
var font_body: Font
var font_bold: Font
var sfx := {}
var music := {}
var players: Array[AudioStreamPlayer] = []
var _pi := 0
var music_player: AudioStreamPlayer
var music_name := ""
var engine: AudioStreamPlayer
var main: Node = null

var data := {
	"xp": 0, "best": 0, "won": 0, "runs": 0, "boss_wins": 0, "missions": 0, "smashed": 0,
	"sound": true, "music": true, "mday": "", "mclaims": 0, "mdone": [],
}
const SAVE_PATH := "user://anti_boredom_3d.cfg"


func _ready() -> void:
	font_title = load("res://fonts/title.ttf")
	font_body = load("res://fonts/body.ttf")
	font_bold = load("res://fonts/bold.ttf")
	for n in SFX:
		sfx[n] = load("res://sfx/%s.wav" % n)
	for n in ["blitz", "menu", "lab"]:
		var s: AudioStreamOggVorbis = load("res://music/%s.ogg" % n)
		s.loop = true
		music[n] = s
	for i in 16:
		var p := AudioStreamPlayer.new()
		add_child(p)
		players.append(p)
	music_player = AudioStreamPlayer.new()
	music_player.volume_db = -8.0
	add_child(music_player)
	engine = AudioStreamPlayer.new()
	var w: AudioStreamWAV = load("res://sfx/engine.wav")
	w.loop_mode = AudioStreamWAV.LOOP_FORWARD
	w.loop_begin = 0
	w.loop_end = 44100
	engine.stream = w
	engine.volume_db = -60.0
	add_child(engine)
	load_game()


# ------------------------------------------------------------------ audio
func play(n: String, pitch := 1.0, vol_db := 0.0) -> void:
	if not data.sound:
		return
	var s = sfx.get(n)
	if s == null:
		return
	var p := players[_pi]
	_pi = (_pi + 1) % players.size()
	p.stream = s
	p.pitch_scale = clampf(pitch, 0.25, 4.0)
	p.volume_db = vol_db
	p.play()


func play_music(n: String, pitch := 1.0) -> void:
	music_player.pitch_scale = pitch
	music_player.stream_paused = false
	if music_name == n and music_player.playing:
		return
	music_name = n
	if not data.music:
		music_player.stop()
		return
	music_player.stream = music[n]
	music_player.play()


func set_music_pitch(p: float) -> void:
	music_player.pitch_scale = p


func stop_music() -> void:
	music_name = ""
	music_player.stop()


func toggle_music() -> void:
	data.music = not data.music
	if data.music:
		var n := music_name
		music_name = ""
		if n != "":
			play_music(n, music_player.pitch_scale)
	else:
		music_player.stop()
	save_game()


# ------------------------------------------------------------------ save / XP
func load_game() -> void:
	var cf := ConfigFile.new()
	if cf.load(SAVE_PATH) == OK:
		for k in data.keys():
			data[k] = cf.get_value("save", k, data[k])


func save_game() -> void:
	var cf := ConfigFile.new()
	for k in data.keys():
		cf.set_value("save", k, data[k])
	cf.save(SAVE_PATH)


func add_xp(n: int) -> bool:
	## returns true when this pushed the player into a new rank
	var before := rank_index()
	data.xp = int(data.xp) + n
	return rank_index() > before


func rank_index() -> int:
	var r := 0
	for i in RANKS.size():
		if int(data.xp) >= RANKS[i][0]:
			r = i
	return r


func rank_name() -> String:
	return RANKS[rank_index()][1]


func rank_progress() -> float:
	var i := rank_index()
	if i >= RANKS.size() - 1:
		return 1.0
	var a: int = RANKS[i][0]
	var b: int = RANKS[i + 1][0]
	return clampf(float(int(data.xp) - a) / float(b - a), 0.0, 1.0)


func next_rank_xp() -> int:
	var i := rank_index()
	if i >= RANKS.size() - 1:
		return int(data.xp)
	return RANKS[i + 1][0]


# ------------------------------------------------------------------ HUD drawing
func chamfer_pts(r: Rect2, cut: float) -> PackedVector2Array:
	cut = minf(cut, minf(r.size.x, r.size.y) * 0.45)
	return PackedVector2Array([
		r.position + Vector2(cut, 0), Vector2(r.end.x, r.position.y), Vector2(r.end.x, r.end.y - cut),
		r.end - Vector2(cut, 0), Vector2(r.position.x, r.end.y), r.position + Vector2(0, cut)])


func chamfer(ci: CanvasItem, r: Rect2, cut: float, fill: Color, edge := Color(0, 0, 0, 0), ew := 3.0) -> void:
	var pts := chamfer_pts(r, cut)
	ci.draw_colored_polygon(pts, fill)
	if edge.a > 0.0 and ew > 0.0:
		var loop := pts.duplicate()
		loop.append(pts[0])
		ci.draw_polyline(loop, edge, ew, true)


func glow_rect(ci: CanvasItem, r: Rect2, cut: float, col: Color, w: float) -> void:
	## soft neon halo around a chamfered rect
	for k in 3:
		var g := (3 - k) * w * 1.6
		var pts := chamfer_pts(r.grow(g * 0.5), cut + g * 0.3)
		pts.append(pts[0])
		ci.draw_polyline(pts, Color(col, 0.07 + k * 0.05), g, true)


func bar(ci: CanvasItem, r: Rect2, f: float, col: Color, back := Color(1, 1, 1, 0.1)) -> void:
	chamfer(ci, r, r.size.y * 0.5, back)
	if f > 0.001:
		var fr := Rect2(r.position, Vector2(maxf(r.size.y, r.size.x * clampf(f, 0.0, 1.0)), r.size.y))
		chamfer(ci, fr, r.size.y * 0.5, col)
		chamfer(ci, Rect2(fr.position + Vector2(2, 2), Vector2(fr.size.x - 4, fr.size.y * 0.35)), r.size.y * 0.3, Color(1, 1, 1, 0.25))


func txt(ci: CanvasItem, pos: Vector2, s: String, size: int, col := WHITE, outline := 0, f: Font = null,
		align := HORIZONTAL_ALIGNMENT_CENTER, oc := INK, glow := 0.0) -> void:
	if f == null:
		f = font_title
	size = maxi(size, 6)
	var w := 4000.0
	var x := pos.x - w * 0.5
	if align == HORIZONTAL_ALIGNMENT_LEFT:
		x = pos.x
	elif align == HORIZONTAL_ALIGNMENT_RIGHT:
		x = pos.x - w
	var base := pos.y + (f.get_ascent(size) - f.get_descent(size)) * 0.5
	if glow > 0.0:
		ci.draw_string_outline(f, Vector2(x, base), s, align, w, size, int(size * 0.35), Color(col, 0.12 * glow))
		ci.draw_string_outline(f, Vector2(x, base), s, align, w, size, int(size * 0.18), Color(col, 0.22 * glow))
	if outline > 0:
		ci.draw_string_outline(f, Vector2(x, base), s, align, w, size, outline, oc)
	ci.draw_string(f, Vector2(x, base), s, align, w, size, col)


func mtxt(ci: CanvasItem, center: Vector2, s: String, size: int, width: float, col := WHITE, f: Font = null, outline := 0, oc := INK) -> void:
	if f == null:
		f = font_body
	var sz := f.get_multiline_string_size(s, HORIZONTAL_ALIGNMENT_CENTER, width, size)
	var top := center.y - sz.y * 0.5 + f.get_ascent(size)
	var pos := Vector2(center.x - width * 0.5, top)
	if outline > 0:
		ci.draw_multiline_string_outline(f, pos, s, HORIZONTAL_ALIGNMENT_CENTER, width, size, -1, outline, oc)
	ci.draw_multiline_string(f, pos, s, HORIZONTAL_ALIGNMENT_CENTER, width, size, -1, col)


func text_width(s: String, size: int, f: Font = null) -> float:
	if f == null:
		f = font_title
	return f.get_string_size(s, HORIZONTAL_ALIGNMENT_LEFT, -1, size).x


func ring(ci: CanvasItem, c: Vector2, r: float, f: float, col: Color, w: float) -> void:
	ci.draw_arc(c, r, 0, TAU, 48, Color(1, 1, 1, 0.12), w, true)
	if f > 0.0:
		ci.draw_arc(c, r, -PI / 2, -PI / 2 + TAU * clampf(f, 0.0, 1.0), 48, col, w, true)


func brackets(ci: CanvasItem, c: Vector2, r: float, col: Color, w := 4.0, rot := 0.0) -> void:
	## targeting reticle corners
	for k in 4:
		var a := rot + PI / 4 + k * PI / 2
		var p := c + Vector2(cos(a), sin(a)) * r
		var d1 := Vector2(cos(a + PI * 0.75), sin(a + PI * 0.75)) * r * 0.45
		var d2 := Vector2(cos(a - PI * 0.75), sin(a - PI * 0.75)) * r * 0.45
		ci.draw_polyline(PackedVector2Array([p + d1, p, p + d2]), col, w, true)

files.scripts/kit.gd:
extends Node
## 3D kit (autoload K): materials, meshes, environments, models and effects.

var _mats := {}
var _curves := {}
var sky_shader: Shader
var grid_shader: Shader
var city_shader: Shader

const ENVS := {
	"night": {top = Color("04030c"), hor = Color("3b0f63"), bot = Color("07050f"), fog = Color("1d0a33"), fogd = 0.012,
		sun = Color("b8c4ff"), sun_e = 1.1, amb = 0.85, stars = 1.0, sun_size = 0.0, neb = 0.5, neb_col = Color("5b1080"), dir = Vector3(-45, 40, 0)},
	"sunset": {top = Color("120a33"), hor = Color("ff5a36"), bot = Color("1c0716"), fog = Color("5a1d3d"), fogd = 0.009,
		sun = Color("ffb07a"), sun_e = 1.2, amb = 0.7, stars = 0.3, sun_size = 0.007, neb = 0.0, neb_col = Color("000000"), dir = Vector3(-12, 160, 0)},
	"space": {top = Color("010104"), hor = Color("0d1240"), bot = Color("010103"), fog = Color("000000"), fogd = 0.0,
		sun = Color("e8eeff"), sun_e = 1.5, amb = 0.6, stars = 1.6, sun_size = 0.012, neb = 1.0, neb_col = Color("2a1a7a"), dir = Vector3(-30, -50, 0)},
	"storm": {top = Color("07080c"), hor = Color("52121c"), bot = Color("0a0507"), fog = Color("2b0b10"), fogd = 0.018,
		sun = Color("ffb09a"), sun_e = 1.2, amb = 0.75, stars = 0.0, sun_size = 0.0, neb = 0.6, neb_col = Color("4a0c14"), dir = Vector3(-55, 20, 0)},
	"bunker": {top = Color("030607"), hor = Color("0b2a2e"), bot = Color("020304"), fog = Color("061416"), fogd = 0.03,
		sun = Color("d0fff6"), sun_e = 1.0, amb = 0.7, stars = 0.0, sun_size = 0.0, neb = 0.0, neb_col = Color("000000"), dir = Vector3(-70, 30, 0)},
	"stadium": {top = Color("02040c"), hor = Color("10204a"), bot = Color("03050a"), fog = Color("0c1630"), fogd = 0.008,
		sun = Color("eaf2ff"), sun_e = 1.4, amb = 0.6, stars = 0.6, sun_size = 0.0, neb = 0.0, neb_col = Color("000000"), dir = Vector3(-60, -30, 0)},
	"void": {top = Color("010203"), hor = Color("06303a"), bot = Color("010203"), fog = Color("031a20"), fogd = 0.02,
		sun = Color("d8fcff"), sun_e = 1.2, amb = 0.7, stars = 0.4, sun_size = 0.0, neb = 0.8, neb_col = Color("004450"), dir = Vector3(-50, 60, 0)},
	"dusk": {top = Color("0c1430"), hor = Color("ff8a3d"), bot = Color("140a10"), fog = Color("3a2030"), fogd = 0.007,
		sun = Color("ffc890"), sun_e = 1.3, amb = 0.75, stars = 0.2, sun_size = 0.006, neb = 0.0, neb_col = Color("000000"), dir = Vector3(-8, 200, 0)},
}


func _ready() -> void:
	sky_shader = load("res://shaders/sky.gdshader")
	grid_shader = load("res://shaders/grid.gdshader")
	city_shader = load("res://shaders/city.gdshader")


# ------------------------------------------------------------------ materials
func mat(col: Color, metal := 0.0, rough := 0.55, emit := 0.0, emit_col := Color(0, 0, 0, 0)) -> StandardMaterial3D:
	var key := "%s|%.2f|%.2f|%.2f|%s" % [col.to_html(), metal, rough, emit, emit_col.to_html()]
	if _mats.has(key):
		return _mats[key]
	var m := StandardMaterial3D.new()
	m.albedo_color = col
	m.metallic = metal
	m.roughness = rough
	if emit > 0.0:
		m.emission_enabled = true
		m.emission = col if emit_col.a == 0.0 else emit_col
		m.emission_energy_multiplier = emit
	if col.a < 1.0:
		m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	_mats[key] = m
	return m


func neon(col: Color, e := 3.0) -> StandardMaterial3D:
	return mat(col, 0.0, 0.4, e)


func unlit(col: Color, add := false) -> StandardMaterial3D:
	var key := "unlit|%s|%s" % [col.to_html(), add]
	if _mats.has(key):
		return _mats[key]
	var m := StandardMaterial3D.new()
	m.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	m.albedo_color = col
	if col.a < 1.0 or add:
		m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	if add:
		m.blend_mode = BaseMaterial3D.BLEND_MODE_ADD
	m.cull_mode = BaseMaterial3D.CULL_DISABLED
	_mats[key] = m
	return m


func fade_mat(col: Color, e := 4.0) -> StandardMaterial3D:
	## a fresh (uncached) glowing transparent material, for things that fade out
	var m := StandardMaterial3D.new()
	m.albedo_color = Color(0, 0, 0, 1)
	m.emission_enabled = true
	m.emission = col
	m.emission_energy_multiplier = e
	m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	m.roughness = 1.0
	m.metallic_specular = 0.0
	m.cull_mode = BaseMaterial3D.CULL_DISABLED
	return m


# ------------------------------------------------------------------ meshes
func add_mesh(parent: Node, mesh: Mesh, m: Material, pos := Vector3.ZERO) -> MeshInstance3D:
	var mi := MeshInstance3D.new()
	mi.mesh = mesh
	mi.material_override = m
	mi.position = pos
	parent.add_child(mi)
	return mi


func box(parent: Node, size: Vector3, pos: Vector3, m: Material) -> MeshInstance3D:
	var bm := BoxMesh.new()
	bm.size = size
	return add_mesh(parent, bm, m, pos)


func sphere(parent: Node, r: float, pos: Vector3, m: Material, seg := 24) -> MeshInstance3D:
	var sm := SphereMesh.new()
	sm.radius = r
	sm.height = r * 2.0
	sm.radial_segments = seg
	sm.rings = seg / 2
	return add_mesh(parent, sm, m, pos)


func cyl(parent: Node, r_top: float, r_bot: float, h: float, pos: Vector3, m: Material, seg := 24) -> MeshInstance3D:
	var cm := CylinderMesh.new()
	cm.top_radius = r_top
	cm.bottom_radius = r_bot
	cm.height = h
	cm.radial_segments = seg
	return add_mesh(parent, cm, m, pos)


func torus(parent: Node, inner: float, outer: float, pos: Vector3, m: Material, seg := 32) -> MeshInstance3D:
	var tm := TorusMesh.new()
	tm.inner_radius = inner
	tm.outer_radius = outer
	tm.rings = seg
	tm.ring_segments = 12
	return add_mesh(parent, tm, m, pos)


func capsule(parent: Node, r: float, h: float, pos: Vector3, m: Material) -> MeshInstance3D:
	var cm := CapsuleMesh.new()
	cm.radius = r
	cm.height = h
	return add_mesh(parent, cm, m, pos)


func prism(parent: Node, size: Vector3, pos: Vector3, m: Material) -> MeshInstance3D:
	var pm := PrismMesh.new()
	pm.size = size
	return add_mesh(parent, pm, m, pos)


func text3d(parent: Node, s: String, font_size: int, depth: float, pos: Vector3, m: Material, px := 0.01) -> MeshInstance3D:
	var tm := TextMesh.new()
	tm.font = G.font_title
	tm.text = s
	tm.font_size = font_size
	tm.depth = depth
	tm.pixel_size = px
	tm.curve_step = 1.0
	return add_mesh(parent, tm, m, pos)


func ground(parent: Node, size: float, line_col: Color, base_col := Color(0.025, 0.02, 0.05), cell := 2.0, energy := 2.2, y := 0.0) -> MeshInstance3D:
	var pm := PlaneMesh.new()
	pm.size = Vector2(size, size)
	var sm := ShaderMaterial.new()
	sm.shader = grid_shader
	sm.set_shader_parameter("line", line_col)
	sm.set_shader_parameter("base", base_col)
	sm.set_shader_parameter("cell", cell)
	sm.set_shader_parameter("energy", energy)
	sm.set_shader_parameter("fade", size * 0.5)
	return add_mesh(parent, pm, sm, Vector3(0, y, 0))


# ------------------------------------------------------------------ environment
func env(parent: Node, kind: String, camera: Camera3D = null, shadows := true, shadow_dist := 45.0) -> DirectionalLight3D:
	var e: Dictionary = ENVS.get(kind, ENVS["night"])
	var en := Environment.new()
	en.background_mode = Environment.BG_SKY
	var sky := Sky.new()
	var sm := ShaderMaterial.new()
	sm.shader = sky_shader
	sm.set_shader_parameter("top_col", e.top)
	sm.set_shader_parameter("hor_col", e.hor)
	sm.set_shader_parameter("bot_col", e.bot)
	sm.set_shader_parameter("stars", e.stars)
	sm.set_shader_parameter("sun_col", e.sun)
	sm.set_shader_parameter("sun_size", e.sun_size)
	sm.set_shader_parameter("nebula", e.neb)
	sm.set_shader_parameter("neb_col", e.neb_col)
	var d: Vector3 = e.dir
	var basis := Basis.from_euler(Vector3(deg_to_rad(d.x), deg_to_rad(d.y), 0))
	sm.set_shader_parameter("sun_dir", basis.z)
	sky.sky_material = sm
	sky.radiance_size = Sky.RADIANCE_SIZE_64
	sky.process_mode = Sky.PROCESS_MODE_QUALITY
	en.sky = sky
	en.ambient_light_source = Environment.AMBIENT_SOURCE_SKY
	en.ambient_light_energy = e.amb
	en.reflected_light_source = Environment.REFLECTION_SOURCE_SKY
	en.tonemap_mode = Environment.TONE_MAPPER_ACES
	en.tonemap_exposure = 1.1
	en.glow_enabled = true
	en.glow_intensity = 0.8
	en.glow_strength = 1.0
	en.glow_bloom = 0.04
	en.glow_hdr_threshold = 1.15
	en.glow_blend_mode = Environment.GLOW_BLEND_MODE_SCREEN
	if e.fogd > 0.0:
		en.fog_enabled = true
		en.fog_light_color = e.fog
		en.fog_density = e.fogd
		en.fog_sky_affect = 0.0
		en.fog_aerial_perspective = 0.0
	en.adjustment_enabled = true
	en.adjustment_saturation = 1.15
	en.adjustment_contrast = 1.06
	if camera != null:
		camera.environment = en
	else:
		var we := WorldEnvironment.new()
		we.environment = en
		parent.add_child(we)
	var sun := DirectionalLight3D.new()
	sun.rotation_degrees = Vector3(d.x, d.y, 0)
	sun.light_color = e.sun
	sun.light_energy = e.sun_e
	sun.shadow_enabled = shadows
	sun.directional_shadow_mode = DirectionalLight3D.SHADOW_ORTHOGONAL
	sun.directional_shadow_max_distance = shadow_dist
	sun.shadow_blur = 1.5
	parent.add_child(sun)
	return sun


func city(parent: Node, center: Vector3, r0: float, r1: float, count: int, seed := 1, hmin := 6.0, hmax := 40.0, clear_x := 0.0, clear_zmax := 999.0) -> void:
	var rng := RandomNumberGenerator.new()
	rng.seed = seed
	var mm := MultiMesh.new()
	mm.transform_format = MultiMesh.TRANSFORM_3D
	mm.use_colors = true
	var bm := BoxMesh.new()
	mm.mesh = bm
	mm.instance_count = count
	var beacons: Array[Vector3] = []
	for i in count:
		var a := rng.randf() * TAU
		var r := sqrt(rng.randf_range(r0 * r0, r1 * r1))
		for tries in 20:
			var px := center.x + cos(a) * r
			var pz := center.z + sin(a) * r
			if absf(px) >= clear_x or pz > clear_zmax:
				break
			a = rng.randf() * TAU
			r = sqrt(rng.randf_range(r0 * r0, r1 * r1))
		var w := rng.randf_range(3.0, 7.0)
		var dpt := rng.randf_range(3.0, 7.0)
		var h := rng.randf_range(hmin, hmax) * (0.6 + 0.4 * (r - r0) / maxf(1.0, r1 - r0)) * rng.randf_range(0.6, 1.4)
		var t := Transform3D(Basis.from_euler(Vector3(0, rng.randf() * TAU, 0)).scaled(Vector3(w, h, dpt)), center + Vector3(cos(a) * r, h * 0.5, sin(a) * r))
		mm.set_instance_transform(i, t)
		var c: Color = G.NEON[rng.randi() % 4]
		mm.set_instance_color(i, Color(c.r, c.g, c.b, rng.randf()))
		if rng.randf() < 0.35:
			beacons.append(center + Vector3(cos(a) * r, h + 0.4, sin(a) * r))
	var mmi := MultiMeshInstance3D.new()
	mmi.multimesh = mm
	var sm := ShaderMaterial.new()
	sm.shader = city_shader
	mmi.material_override = sm
	mmi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	parent.add_child(mmi)
	if beacons.size() > 0:
		var bmm := MultiMesh.new()
		bmm.transform_format = MultiMesh.TRANSFORM_3D
		var s := SphereMesh.new()
		s.radius = 0.35
		s.height = 0.7
		s.radial_segments = 8
		s.rings = 4
		bmm.mesh = s
		bmm.instance_count = beacons.size()
		for i in beacons.size():
			bmm.set_instance_transform(i, Transform3D(Basis(), beacons[i]))
		var bi := MultiMeshInstance3D.new()
		bi.multimesh = bmm
		bi.material_override = neon(Color("ff2e4d"), 5.0)
		bi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		parent.add_child(bi)


# ------------------------------------------------------------------ models
func drone(parent: Node, col: Color) -> Node3D:
	## the player's hover-drone. rotors are stored in meta "rotors"
	var root := Node3D.new()
	parent.add_child(root)
	var body := mat(Color("4e5878"), 0.5, 0.3)
	var trim := neon(col, 3.5)
	var hull := sphere(root, 0.55, Vector3.ZERO, body)
	hull.scale = Vector3(1.0, 0.42, 1.25)
	box(root, Vector3(0.7, 0.08, 0.9), Vector3(0, 0.2, 0), mat(Color("2a2f45"), 0.8, 0.3))
	var visor := sphere(root, 0.22, Vector3(0, 0.05, -0.5), trim, 16)
	visor.scale = Vector3(1.4, 0.55, 0.6)
	var rotors: Array = []
	for sx in [-1.0, 1.0]:
		for sz in [-1.0, 1.0]:
			var tip := Vector3(sx * 0.95, 0.05, sz * 0.85)
			var arm := box(root, Vector3(0.12, 0.08, 0.9), tip * 0.5, body)
			arm.look_at_from_position(tip * 0.5, tip, Vector3.UP)
			cyl(root, 0.12, 0.12, 0.16, tip, body, 12)
			var ring := torus(root, 0.36, 0.42, tip + Vector3(0, 0.05, 0), trim, 24)
			ring.scale = Vector3(1, 0.6, 1)
			var rot := box(root, Vector3(0.62, 0.02, 0.08), tip + Vector3(0, 0.12, 0), unlit(Color(0.8, 0.9, 1.0, 0.55)))
			rotors.append(rot)
	box(root, Vector3(0.9, 0.04, 0.05), Vector3(0, -0.02, 0.62), trim)
	var glow := OmniLight3D.new()
	glow.light_color = col
	glow.light_energy = 1.6
	glow.omni_range = 4.0
	glow.position = Vector3(0, 0.9, 0.6)
	root.add_child(glow)
	root.set_meta("rotors", rotors)
	return root


func spin_rotors(d: Node3D, dt: float) -> void:
	if d.has_meta("rotors"):
		for r in d.get_meta("rotors"):
			(r as Node3D).rotate_y(dt * 40.0)


func graylord(parent: Node, s := 1.0) -> Node3D:
	## the villain: a giant armoured grey cube with a red eye. "eye" and "rings" in meta
	var root := Node3D.new()
	parent.add_child(root)
	var armor := mat(Color("7d8396"), 0.55, 0.35)
	var dark := mat(Color("3d4150"), 0.5, 0.4)
	box(root, Vector3(4, 4, 4) * s, Vector3.ZERO, armor)
	for f in 6:
		var n: Vector3 = [Vector3.RIGHT, Vector3.LEFT, Vector3.UP, Vector3.DOWN, Vector3.BACK, Vector3.FORWARD][f]
		for k in 4:
			var u := Vector3(n.y, n.z, n.x) if absf(n.x) < 0.5 else Vector3(0, 1, 0)
			var v := n.cross(u)
			var off := (u * (k % 2 - 0.5) + v * (k / 2 - 0.5)) * 1.9 * s
			var p := box(root, Vector3.ONE * 1.6 * s, n * 1.95 * s + off, dark)
			p.scale = Vector3.ONE - n.abs() * 0.9
	var eye_bar := box(root, Vector3(3.0, 0.5, 0.2) * s, Vector3(0, 0.5, 2.05) * s, mat(Color("12131a"), 0.5, 0.4))
	eye_bar.name = "EyeBar"
	var eye := box(root, Vector3(2.4, 0.22, 0.1) * s, Vector3(0, 0.5, 2.18) * s, neon(Color("ff1f3d"), 6.0))
	var ring1 := torus(root, 3.4 * s, 3.6 * s, Vector3.ZERO, neon(Color("ff1f3d"), 2.5), 48)
	ring1.rotation_degrees = Vector3(90, 0, 0)
	var ring2 := torus(root, 3.9 * s, 4.0 * s, Vector3.ZERO, mat(Color("3a3e4f"), 0.9, 0.3), 48)
	ring2.rotation_degrees = Vector3(70, 0, 30)
	var l := OmniLight3D.new()
	l.light_color = Color("ff2a40")
	l.light_energy = 3.0
	l.omni_range = 10.0 * s
	l.position = Vector3(0, 0.5, 3.0) * s
	root.add_child(l)
	root.set_meta("eye", eye)
	root.set_meta("rings", [ring1, ring2])
	return root


# ------------------------------------------------------------------ effects
func curve(kind: String) -> Curve:
	if _curves.has(kind):
		return _curves[kind]
	var c := Curve.new()
	match kind:
		"fade":
			c.add_point(Vector2(0, 1))
			c.add_point(Vector2(1, 0))
		"grow":
			c.add_point(Vector2(0, 0.4))
			c.add_point(Vector2(1, 1.6))
			c.max_value = 2.0
		"pop":
			c.add_point(Vector2(0, 0.2))
			c.add_point(Vector2(0.15, 1.0))
			c.add_point(Vector2(1, 0))
	_curves[kind] = c
	return c


func _particles(parent: Node, pos: Vector3, mesh: Mesh, m: Material, amount: int, life: float) -> CPUParticles3D:
	var p := CPUParticles3D.new()
	p.mesh = mesh
	p.material_override = m
	p.amount = amount
	p.lifetime = life
	p.one_shot = true
	p.explosiveness = 0.95
	p.local_coords = false
	p.position = pos
	parent.add_child(p)
	return p


func _expire(n: Node, t: float) -> void:
	n.get_tree().create_timer(t).timeout.connect(n.queue_free)


func sparks(parent: Node, pos: Vector3, col: Color, n := 24, speed := 9.0, size := 1.0) -> void:
	var bm := BoxMesh.new()
	bm.size = Vector3(0.05, 0.32, 0.05) * size
	var p := _particles(parent, pos, bm, neon(col, 5.0), n, 0.7)
	p.particle_flag_align_y = true
	p.direction = Vector3.UP
	p.spread = 180.0
	p.initial_velocity_min = speed * 0.5
	p.initial_velocity_max = speed
	p.gravity = Vector3(0, -16, 0)
	p.damping_min = 1.0
	p.damping_max = 3.0
	p.scale_amount_curve = curve("fade")
	p.emitting = true
	_expire(p, 1.5)


func boom(parent: Node, pos: Vector3, size := 1.0, col := Color("ff7a1a"), debris := Color("4a4e5e")) -> void:
	var root := Node3D.new()
	parent.add_child(root)
	root.position = pos
	var l := OmniLight3D.new()
	l.light_color = col.lerp(Color(1, 0.85, 0.6), 0.4)
	l.light_energy = 8.0
	l.omni_range = 9.0 * size
	root.add_child(l)
	var tw := root.create_tween().set_parallel(true)
	tw.tween_property(l, "light_energy", 0.0, 0.45)
	# fireball + hot core
	for k in 2:
		var fm := fade_mat(col if k == 0 else Color(1, 0.92, 0.7), 5.0 if k == 0 else 8.0)
		var s := sphere(root, 0.5, Vector3.ZERO, fm, 20)
		var s0 := (0.4 if k == 0 else 0.3) * size
		var s1 := (2.6 if k == 0 else 1.4) * size
		s.scale = Vector3.ONE * s0
		tw.tween_property(s, "scale", Vector3.ONE * s1, 0.38 if k == 0 else 0.22).set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_EXPO)
		tw.tween_property(fm, "albedo_color:a", 0.0, 0.42 if k == 0 else 0.22).set_ease(Tween.EASE_IN)
	# shockwave
	var rm := fade_mat(Color(1, 0.8, 0.6), 3.0)
	var ring := torus(root, 0.92, 1.0, Vector3.ZERO, rm, 40)
	ring.scale = Vector3(0.3, 0.05, 0.3) * size
	tw.tween_property(ring, "scale", Vector3(5.0, 0.3, 5.0) * size, 0.45).set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_CUBIC)
	tw.tween_property(rm, "albedo_color:a", 0.0, 0.45)
	# sparks
	sparks(root, Vector3.ZERO, Color(1, 0.75, 0.3), int(36 * clampf(size, 0.6, 1.6)), 14.0 * size, size)
	# debris chunks
	var cm := BoxMesh.new()
	cm.size = Vector3.ONE * 0.28 * size
	var dp := _particles(root, Vector3.ZERO, cm, mat(debris, 0.6, 0.5), int(16 * clampf(size, 0.6, 1.6)), 1.3)
	dp.direction = Vector3.UP
	dp.spread = 75.0
	dp.initial_velocity_min = 5.0 * size
	dp.initial_velocity_max = 11.0 * size
	dp.gravity = Vector3(0, -22, 0)
	dp.angular_velocity_min = -720
	dp.angular_velocity_max = 720
	dp.angle_min = 0
	dp.angle_max = 360
	dp.scale_amount_min = 0.5
	dp.scale_amount_max = 1.4
	dp.particle_flag_rotate_y = true
	dp.emitting = true
	# smoke
	var smm := SphereMesh.new()
	smm.radius = 0.6 * size
	smm.height = 1.2 * size
	smm.radial_segments = 10
	smm.rings = 6
	var smat := StandardMaterial3D.new()
	smat.vertex_color_use_as_albedo = true
	smat.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	smat.roughness = 1.0
	var sp := _particles(root, Vector3(0, 0.3 * size, 0), smm, smat, 12, 1.8)
	sp.explosiveness = 0.8
	sp.direction = Vector3.UP
	sp.spread = 70.0
	sp.initial_velocity_min = 1.0 * size
	sp.initial_velocity_max = 3.5 * size
	sp.gravity = Vector3(0, 1.2, 0)
	sp.damping_min = 1.5
	sp.damping_max = 2.5
	sp.scale_amount_curve = curve("grow")
	var gr := Gradient.new()
	gr.set_color(0, Color(0.22, 0.18, 0.2, 0.75))
	gr.set_color(1, Color(0.1, 0.1, 0.12, 0.0))
	sp.color_ramp = gr
	sp.emitting = true
	_expire(root, 2.4)


func beam(parent: Node, a: Vector3, b: Vector3, col: Color, width := 0.08, life := 0.18) -> void:
	var len := a.distance_to(b)
	if len < 0.01:
		return
	var m := fade_mat(col, 6.0)
	var c := cyl(parent, width, width, len, (a + b) * 0.5, m, 8)
	c.look_at_from_position((a + b) * 0.5, b, Vector3.UP if absf((b - a).normalized().y) < 0.99 else Vector3.RIGHT)
	c.rotate_object_local(Vector3.RIGHT, PI / 2)
	var core := cyl(c, width * 0.4, width * 0.4, len, Vector3.ZERO, fade_mat(Color(1, 1, 1), 8.0), 6)
	var tw := c.create_tween().set_parallel(true)
	tw.tween_property(m, "albedo_color:a", 0.0, life)
	tw.tween_property(core.material_override, "albedo_color:a", 0.0, life * 0.7)
	tw.tween_property(c, "scale", Vector3(0.2, 1.0, 0.2), life)
	_expire(c, life + 0.05)


func flash_ring(parent: Node, pos: Vector3, col: Color, r := 1.0, normal := Vector3.UP) -> void:
	var m := fade_mat(col, 4.0)
	var t := torus(parent, 0.85, 1.0, pos, m, 32)
	if normal != Vector3.UP:
		t.look_at_from_position(pos, pos + normal, Vector3.UP if absf(normal.y) < 0.99 else Vector3.RIGHT)
		t.rotate_object_local(Vector3.RIGHT, PI / 2)
	t.scale = Vector3(0.2, 0.2, 0.2) * r
	var tw := t.create_tween().set_parallel(true)
	tw.tween_property(t, "scale", Vector3(1.8, 0.4, 1.8) * r, 0.35).set_ease(Tween.EASE_OUT)
	tw.tween_property(m, "albedo_color:a", 0.0, 0.35)
	_expire(t, 0.4)

