extends "res://scripts/screen3d.gd"
## SMASH LAB: physics destruction sandbox.

const MAPS := ["TOWER", "WALL", "CITY"]
const TOOLS := [["CANNON", Color("00e5ff")], ["BOMB", Color("ff7a1a")], ["ROCKET", Color("ff2bd6")], ["MEGA", Color("ff2e4d")]]
const MAX_BODIES := 260

var world_root: Node3D
var blocks: Array = []      # {b: RigidBody3D, start: Vector3, kind: String, scored: bool}
var projectiles: Array = []
var bombs: Array = []
var rockets: Array = []
var map_i := 0
var tool_i := 0
var damage := 0
var shown_damage := 0.0
var yaw := 0.6
var pitch := 0.32
var dist := 22.0
var focus := Vector3(0, 3, 0)
var touch_start := {}
var slowmo := false
var tool_btns: Array = []
var map_btn: Dictionary
var reset_btn: Dictionary
var slow_btn: Dictionary
var b_back: Dictionary
var mats := {}
var combo := 0
var combo_t := 0.0
var launcher: Node3D


func setup() -> void:
	K.env(self, "night", null, true, 60.0)
	K.ground(self, 300.0, G.ORANGE, Color(0.05, 0.045, 0.05), 2.0, 0.9, 0.0)
	K.city(self, Vector3.ZERO, 45.0, 160.0, 200, 33)
	# physics floor
	var floor_b := StaticBody3D.new()
	var fs := CollisionShape3D.new()
	var bs := BoxShape3D.new()
	bs.size = Vector3(200, 2, 200)
	fs.shape = bs
	fs.position = Vector3(0, -1, 0)
	floor_b.add_child(fs)
	add_child(floor_b)
	# arena markers
	for k in 12:
		var a := k * TAU / 12.0
		var p := Vector3(cos(a), 0, sin(a)) * 16.0
		K.cyl(self, 0.15, 0.2, 2.5, p + Vector3(0, 1.25, 0), K.mat(Color("2a2e3c"), 0.5, 0.4), 8)
		K.sphere(self, 0.22, p + Vector3(0, 2.6, 0), K.neon(G.ORANGE, 4.0), 10)
	var key := OmniLight3D.new()
	key.position = Vector3(6, 14, 10)
	key.light_energy = 3.0
	key.omni_range = 40.0
	key.light_color = Color("ffe6cc")
	add_child(key)
	mats = {
		"concrete": K.mat(Color("9a9ca4"), 0.0, 0.85),
		"wood": K.mat(Color("a8743f"), 0.0, 0.7),
		"steel": K.mat(Color("7f8aa0"), 0.6, 0.35),
		"glass": K.mat(Color(0.55, 0.9, 1.0, 0.35), 0.2, 0.05, 0.4),
		"brick": K.mat(Color("a2493a"), 0.0, 0.8),
		"gray": K.mat(Color("6c7080"), 0.3, 0.6),
	}
	cam = Camera3D.new()
	cam.fov = 58
	add_child(cam)
	for i in TOOLS.size():
		var tb := add_button(TOOLS[i][0], TOOLS[i][1], func(): pick_tool(i), 30)
		tool_btns.append(tb)
	map_btn = add_button("MAP: TOWER", G.CYAN, next_map, 26)
	reset_btn = add_button("RESET", G.LIME, func(): build_map(), 26)
	slow_btn = add_button("SLOW-MO", G.PURPLE, toggle_slow, 26)
	b_back = add_back(func(): G.main.go("title"))
	G.play_music("lab")
	build_map()
	pick_tool(0)


func _exit_tree() -> void:
	Engine.time_scale = 1.0
	G.save_game()


func layout() -> void:
	place_back(b_back)
	var n := TOOLS.size()
	var bw := minf(200.0 * U, (W - 60 * U) / n - 16 * U)
	var bh := 96.0 * U
	var x0 := W * 0.5 - (n * bw + (n - 1) * 16 * U) * 0.5
	for i in n:
		tool_btns[i].rect = Rect2(x0 + i * (bw + 16 * U), H - bh - 24 * U, bw, bh)
	var sw := 230.0 * U
	map_btn.rect = Rect2(W - sw - 24 * U, 24 * U, sw, 70 * U)
	reset_btn.rect = Rect2(W - sw - 24 * U, 104 * U, sw, 70 * U)
	slow_btn.rect = Rect2(W - sw - 24 * U, 184 * U, sw, 70 * U)


func pick_tool(i: int) -> void:
	tool_i = i
	for k in tool_btns.size():
		tool_btns[k].big = k == i


func toggle_slow() -> void:
	slowmo = not slowmo
	Engine.time_scale = 0.3 if slowmo else 1.0
	slow_btn.big = slowmo
	G.set_music_pitch(0.75 if slowmo else 1.0)


func next_map() -> void:
	map_i = (map_i + 1) % MAPS.size()
	map_btn.text = "MAP: " + MAPS[map_i]
	build_map()


# ------------------------------------------------------------------ building
func clear_world() -> void:
	if world_root:
		world_root.queue_free()
	world_root = Node3D.new()
	add_child(world_root)
	blocks.clear()
	projectiles.clear()
	bombs.clear()
	rockets.clear()
	damage = 0
	shown_damage = 0.0


func add_block(size: Vector3, pos: Vector3, kind: String, rot := 0.0) -> RigidBody3D:
	var rb := RigidBody3D.new()
	var cs := CollisionShape3D.new()
	var sh := BoxShape3D.new()
	sh.size = size
	cs.shape = sh
	rb.add_child(cs)
	K.box(rb, size, Vector3.ZERO, mats[kind])
	var dens := {"concrete": 2.4, "wood": 0.7, "steel": 3.0, "glass": 1.2, "brick": 1.8, "gray": 1.5}
	rb.mass = maxf(0.2, size.x * size.y * size.z * dens.get(kind, 1.0))
	rb.position = pos
	rb.rotation.y = rot
	rb.can_sleep = true
	rb.sleeping = true
	var pm := PhysicsMaterial.new()
	pm.friction = 0.8
	pm.bounce = 0.05
	rb.physics_material_override = pm
	world_root.add_child(rb)
	if kind == "glass":
		rb.contact_monitor = true
		rb.max_contacts_reported = 2
		rb.body_entered.connect(func(_o): glass_hit(rb))
	blocks.append({b = rb, start = pos, kind = kind, scored = false, size = size})
	return rb


func build_map() -> void:
	clear_world()
	match MAPS[map_i]:
		"TOWER":
			# a hollow tower with glass windows, plus a crate pyramid
			for lv in 9:
				var y := 0.5 + lv * 1.0
				for k in 8:
					var a := k * TAU / 8.0 + (lv % 2) * TAU / 16.0
					var p := Vector3(cos(a) * 2.2, y, sin(a) * 2.2)
					var kind := "glass" if (lv % 3 == 1 and k % 2 == 0) else ("concrete" if lv % 2 == 0 else "gray")
					add_block(Vector3(1.6, 1.0, 0.7), p, kind, -a + PI / 2)
			add_block(Vector3(5.6, 0.4, 5.6), Vector3(0, 9.2, 0), "steel")
			for row in 4:
				for k in 4 - row:
					add_block(Vector3(1, 1, 1), Vector3(-7.0 + k * 1.05 + row * 0.52, 0.5 + row * 1.0, 4.0), "wood")
					add_block(Vector3(1, 1, 1), Vector3(5.0 + k * 1.05 + row * 0.52, 0.5 + row * 1.0, -4.0), "wood")
			focus = Vector3(0, 4, 0)
		"WALL":
			for row in 10:
				var off := 0.5 if row % 2 == 1 else 0.0
				for k in 11:
					var x := -6.0 + k * 1.2 + off
					var kind := "brick"
					if row >= 3 and row <= 5 and (k == 3 or k == 7):
						kind = "glass"
					add_block(Vector3(1.18, 0.55, 0.7), Vector3(x, 0.28 + row * 0.56, 0), kind)
			for k in 4:
				add_block(Vector3(0.9, 0.9, 0.9), Vector3(-4.5 + k * 3.0, 0.45, 3.5), "steel")
			focus = Vector3(0, 3, 0)
		"CITY":
			var spots := [Vector3(-5, 0, -3), Vector3(0, 0, -5), Vector3(5, 0, -2), Vector3(-3, 0, 3), Vector3(3.5, 0, 3.5)]
			for i in spots.size():
				var h := 3 + (i * 2) % 5
				var c: Vector3 = spots[i]
				for lv in h:
					for k in 4:
						var p := c + Vector3((k % 2 - 0.5) * 1.02, 0.5 + lv * 1.0, (k / 2 - 0.5) * 1.02)
						var kind := "glass" if (lv % 2 == 1 and k % 3 == 0) else ("concrete" if i % 2 == 0 else "gray")
						add_block(Vector3(1, 1, 1), p, kind)
				add_block(Vector3(2.2, 0.3, 2.2), c + Vector3(0, h + 0.15, 0), "steel")
			focus = Vector3(0, 2.5, 0)


func glass_hit(rb: RigidBody3D) -> void:
	if not is_instance_valid(rb) or rb.is_queued_for_deletion():
		return
	if rb.linear_velocity.length() > 4.0:
		shatter(rb)


func shatter(rb: RigidBody3D) -> void:
	var idx := -1
	for i in blocks.size():
		if blocks[i].b == rb:
			idx = i
			break
	if idx < 0:
		return
	var info: Dictionary = blocks[idx]
	blocks.remove_at(idx)
	var p := rb.global_position
	var v := rb.linear_velocity
	rb.queue_free()
	add_damage(250, p)
	G.play("shatter", randf_range(0.9, 1.15), -2.0)
	K.sparks(world_root, p, Color(0.7, 0.95, 1.0), 14, 5.0, 0.6)
	if blocks.size() < MAX_BODIES:
		var s: Vector3 = info.size
		for k in 4:
			var sb := add_block(s * Vector3(0.45, 0.45, 0.5), p + Vector3(randf_range(-0.3, 0.3), randf_range(-0.3, 0.3), randf_range(-0.2, 0.2)), "glass")
			sb.sleeping = false
			sb.contact_monitor = false
			sb.linear_velocity = v + Vector3(randf_range(-3, 3), randf_range(0, 3), randf_range(-3, 3))
			blocks[blocks.size() - 1].scored = true


# ------------------------------------------------------------------ weapons
func pick_point(p: Vector2) -> Dictionary:
	var o := cam.project_ray_origin(p)
	var d := cam.project_ray_normal(p)
	var q := PhysicsRayQueryParameters3D.create(o, o + d * 200.0)
	var hit := get_world_3d().direct_space_state.intersect_ray(q)
	if hit.is_empty():
		var k := -o.y / d.y if d.y < -0.001 else 60.0
		return {pos = o + d * k, dir = d}
	return {pos = hit.position, dir = d}


func fire(p: Vector2) -> void:
	var tgt := pick_point(p)
	match TOOLS[tool_i][0]:
		"CANNON":
			var rb := RigidBody3D.new()
			var cs := CollisionShape3D.new()
			var sh := SphereShape3D.new()
			sh.radius = 0.55
			cs.shape = sh
			rb.add_child(cs)
			K.sphere(rb, 0.55, Vector3.ZERO, K.mat(Color("23262f"), 0.8, 0.25), 18)
			K.sphere(rb, 0.6, Vector3.ZERO, K.unlit(Color(0.0, 0.9, 1.0, 0.25), true), 14)
			rb.mass = 40.0
			rb.continuous_cd = true
			var start := cam.global_position + cam.global_transform.basis.x * 1.2 - cam.global_transform.basis.y * 0.8
			rb.position = start
			world_root.add_child(rb)
			rb.linear_velocity = (tgt.pos - start).normalized() * 48.0
			projectiles.append({b = rb, t = 0.0})
			G.play("thud", 0.6)
			G.play("laser2", 0.5, -6.0)
			shake(0.2)
		"BOMB":
			var bomb := RigidBody3D.new()
			var cs2 := CollisionShape3D.new()
			var sh2 := SphereShape3D.new()
			sh2.radius = 0.5
			cs2.shape = sh2
			bomb.add_child(cs2)
			K.sphere(bomb, 0.5, Vector3.ZERO, K.mat(Color("15161c"), 0.6, 0.3), 16)
			var light := K.sphere(bomb, 0.16, Vector3(0, 0.52, 0), K.neon(G.RED, 6.0), 8)
			bomb.mass = 5.0
			bomb.position = tgt.pos + Vector3(0, 6, 0)
			world_root.add_child(bomb)
			bombs.append({b = bomb, t = 1.6, light = light, r = 6.5, f = 26.0})
			G.play("beep")
		"ROCKET":
			var r := Node3D.new()
			world_root.add_child(r)
			K.cyl(r, 0.0, 0.22, 0.6, Vector3(0, 0, -0.9), K.mat(G.RED, 0.5, 0.3), 12).rotation.x = -PI / 2
			var body := K.cyl(r, 0.22, 0.22, 1.4, Vector3.ZERO, K.mat(Color("e8ecf6"), 0.5, 0.3), 12)
			body.rotation.x = PI / 2
			var fl := K.cyl(r, 0.2, 0.0, 1.2, Vector3(0, 0, 1.2), K.neon(Color("ff9a3a"), 6.0), 10)
			fl.rotation.x = PI / 2
			var start := cam.global_position - cam.global_transform.basis.x * 2.5 + Vector3(0, 1.0, 0)
			r.position = start
			r.look_at(tgt.pos, Vector3.UP)
			rockets.append({n = r, from = start, to = tgt.pos, f = 0.0, time = maxf(0.35, start.distance_to(tgt.pos) / 40.0)})
			G.play("rocket", 1.4, -2.0)
		"MEGA":
			var mb := Node3D.new()
			world_root.add_child(mb)
			var shell := K.capsule(mb, 0.8, 3.0, Vector3.ZERO, K.mat(Color("2b2e3a"), 0.6, 0.35))
			shell.name = "Shell"
			K.cyl(mb, 0.82, 0.82, 0.3, Vector3(0, 0.3, 0), K.neon(G.YELLOW, 4.0), 16)
			for k in 4:
				var fin := K.box(mb, Vector3(0.08, 0.8, 0.9), Vector3(0, 1.4, 0), K.mat(Color("3d4150"), 0.6, 0.35))
				fin.rotation.y = k * PI / 2
			mb.position = tgt.pos + Vector3(0, 40, 0)
			bombs.append({b = mb, t = 1.3, light = null, r = 14.0, f = 70.0, mega = true, to = tgt.pos})
			G.play("whoosh", 0.5)


func explode(pos: Vector3, radius: float, force: float, size: float) -> void:
	K.boom(world_root, pos, size, Color("ff7a1a"), Color("6c7080"))
	G.play("boom", randf_range(0.85, 1.0) / sqrt(size))
	shake(0.5 * size)
	for info in blocks.duplicate():
		var b: RigidBody3D = info.b
		if not is_instance_valid(b):
			continue
		var d := b.global_position - pos
		var l := d.length()
		if l < radius:
			var fall := 1.0 - l / radius
			if info.kind == "glass" and fall > 0.25:
				shatter(b)
				continue
			b.sleeping = false
			var dir := (d.normalized() + Vector3(0, 0.6, 0)).normalized()
			b.apply_impulse(dir * force * fall * b.mass * 0.35, Vector3(randf_range(-0.2, 0.2), randf_range(-0.2, 0.2), randf_range(-0.2, 0.2)))
	for pr in projectiles:
		var pb: RigidBody3D = pr.b
		if is_instance_valid(pb) and pb.global_position.distance_to(pos) < radius:
			pb.apply_central_impulse((pb.global_position - pos).normalized() * force * 2.0)


func add_damage(v: int, at: Vector3) -> void:
	damage += v
	combo += 1
	combo_t = 1.2
	if randf() < 0.12 or v >= 250:
		fx.text(cam.unproject_position(at), "+$%d" % v, G.YELLOW, 30 * U)


# ------------------------------------------------------------------ loop / input
func update(dt: float) -> void:
	var sdt := dt
	var udt := dt / maxf(Engine.time_scale, 0.01)
	combo_t -= udt
	if combo_t <= 0.0:
		combo = 0
	shown_damage = move_toward(shown_damage, damage, maxf(50.0, (damage - shown_damage) * 6.0) * udt)
	if damage > int(G.data.smashed):
		G.data.smashed = damage
	# camera orbit
	yaw += udt * 0.04
	var off := Vector3(sin(yaw) * cos(pitch), sin(pitch), cos(yaw) * cos(pitch)) * dist
	cam.position = focus + off
	cam.look_at(focus, Vector3.UP)
	# bombs
	var i := bombs.size() - 1
	while i >= 0:
		var bm: Dictionary = bombs[i]
		bm.t -= sdt
		if bm.get("mega", false):
			var n: Node3D = bm.b
			n.position = n.position.move_toward(bm.to + Vector3(0, 1.5, 0), sdt * 34.0)
			n.rotate_y(sdt * 3.0)
			if n.position.y <= bm.to.y + 1.6:
				bm.t = 0.0
		elif bm.light:
			(bm.light as Node3D).visible = fmod(bm.t, 0.3) > 0.15
		if bm.t <= 0.0:
			var at: Vector3 = (bm.b as Node3D).global_position
			(bm.b as Node3D).queue_free()
			bombs.remove_at(i)
			if bm.get("mega", false):
				explode(at, bm.r, bm.f, 3.2)
				K.flash_ring(world_root, at + Vector3(0, 0.3, 0), Color(1, 0.8, 0.5), 8.0)
				for k in 5:
					K.boom(world_root, at + Vector3(randf_range(-4, 4), randf_range(0, 3), randf_range(-4, 4)), 1.6)
				G.play("boom", 0.55)
				shake(2.0)
			else:
				explode(at, bm.r, bm.f, 1.4)
		i -= 1
	# rockets
	i = rockets.size() - 1
	while i >= 0:
		var r: Dictionary = rockets[i]
		r.f += sdt / r.time
		var n2: Node3D = r.n
		n2.position = (r.from as Vector3).lerp(r.to, minf(r.f, 1.0))
		if r.f >= 1.0:
			n2.queue_free()
			rockets.remove_at(i)
			explode(r.to, 5.5, 24.0, 1.3)
		i -= 1
	# cannonballs expire
	i = projectiles.size() - 1
	while i >= 0:
		projectiles[i].t += sdt
		var pb: RigidBody3D = projectiles[i].b
		if projectiles[i].t > 8.0 or not is_instance_valid(pb) or pb.global_position.y < -20:
			if is_instance_valid(pb):
				pb.queue_free()
			projectiles.remove_at(i)
		i -= 1
	# scoring: blocks knocked from their spot
	for info in blocks:
		if info.scored:
			continue
		var b: RigidBody3D = info.b
		if not is_instance_valid(b):
			continue
		if b.global_position.distance_to(info.start) > 1.2 or b.global_transform.basis.y.dot(Vector3.UP) < 0.6:
			info.scored = true
			var val := {"concrete": 150, "wood": 80, "steel": 300, "glass": 250, "brick": 100, "gray": 120}
			add_damage(val.get(info.kind, 100), b.global_position)
			if randf() < 0.3:
				G.play(["crunch", "thud", "clank"][randi() % 3], randf_range(0.8, 1.2), -6.0)


func down(p: Vector2, i: int) -> void:
	touch_start[i] = {p = p, t = T, moved = 0.0}


func drag(_p: Vector2, i: int, rel: Vector2) -> void:
	if touch_start.has(i):
		touch_start[i].moved += rel.length()
		if touch_start[i].moved > 14.0:
			yaw -= rel.x * 0.006
			pitch = clampf(pitch + rel.y * 0.004, 0.08, 1.2)


func up(p: Vector2, i: int) -> void:
	if touch_start.has(i):
		var ts: Dictionary = touch_start[i]
		touch_start.erase(i)
		if ts.moved < 14.0:
			fire(p)


func paint() -> void:
	var s := "$%s" % _commas(int(shown_damage))
	G.txt(hud, Vector2(W * 0.5, 50 * U), "DAMAGE", int(24 * U), G.ORANGE, 0, G.font_title, HORIZONTAL_ALIGNMENT_CENTER, G.INK, 0.8)
	G.txt(hud, Vector2(W * 0.5, 104 * U), s, int(66 * U), G.WHITE, 0, G.font_title, HORIZONTAL_ALIGNMENT_CENTER, G.INK, 1.0)
	if combo >= 5:
		G.txt(hud, Vector2(W * 0.5, 160 * U), "COMBO x%d" % combo, int(34 * U), G.YELLOW, 0, G.font_title, HORIZONTAL_ALIGNMENT_CENTER, G.INK, 1.0)
	G.txt(hud, Vector2(W * 0.5, H - 140 * U), "Tap to fire  -  drag to look around", int(22 * U), Color(1, 1, 1, 0.7), 0, G.font_body)
	G.txt(hud, Vector2(W * 0.5, 186 * U if combo >= 5 else 150 * U), "RECORD $%s" % _commas(int(G.data.smashed)), int(20 * U), G.STEEL, 0, G.font_body)
	if slowmo:
		hud.draw_rect(Rect2(0, 0, W, H), Color(0.3, 0.1, 0.6, 0.12))


func _commas(n: int) -> String:
	var s := str(n)
	var out := ""
	while s.length() > 3:
		out = "," + s.substr(s.length() - 3) + out
		s = s.substr(0, s.length() - 3)
	return s + out

