extends Node
## Root: owns the current screen and the slash-wipe transition.

const SCREENS := {
	"title": "title", "blitz": "blitz", "lab": "lab", "missions": "missions", "bored": "bored",
}

var wipe_layer: CanvasLayer
var wipe_rect: ColorRect
var wipe_mat: ShaderMaterial
var cur: Node = null
var busy := false


func _ready() -> void:
	G.main = self
	wipe_layer = CanvasLayer.new()
	wipe_layer.layer = 50
	add_child(wipe_layer)
	wipe_rect = ColorRect.new()
	wipe_rect.mouse_filter = Control.MOUSE_FILTER_IGNORE
	wipe_mat = ShaderMaterial.new()
	wipe_mat.shader = load("res://shaders/wipe.gdshader")
	wipe_mat.set_shader_parameter("r", 2.0)
	wipe_rect.material = wipe_mat
	wipe_layer.add_child(wipe_rect)
	get_viewport().size_changed.connect(_resize)
	_resize()
	var args := OS.get_cmdline_user_args()
	if "--check" in args:
		for d in ["res://scripts/", "res://scripts/micro/"]:
			for f in DirAccess.get_files_at(d):
				if f.ends_with(".gd"):
					var r = load(d + f)
					if r == null:
						print("FAILED ", d + f)
		print("CHECK_DONE")
		get_tree().quit()
		return
	if "--selftest" in args:
		var t = load("res://scripts/selftest.gd").new()
		add_child(t)
		return
	var start := "title"
	var start_arg = null
	for a in args:
		if a.begins_with("--screen="):
			start = a.substr(9)
		if a.begins_with("--micro="):
			start = "blitz"
			start_arg = {"only": a.substr(8)}
	if OS.has_feature("web"):
		var h = JavaScriptBridge.eval("location.hash", true)
		if h is String and h.begins_with("#s-"):
			start = h.substr(3)
		elif h is String and h.begins_with("#m-"):
			start = "blitz"
			start_arg = {"only": h.substr(3)}
	_show(start, start_arg)
	if "--poke" in args:
		_poke()


func _poke() -> void:
	## random touches for headless smoke tests
	var vs := get_viewport().get_visible_rect().size
	var p := Vector2(randf() * vs.x, randf() * vs.y)
	for k in 600:
		await get_tree().process_frame
		var e
		match k % 8:
			0:
				p = Vector2(randf_range(0.15, 0.85) * vs.x, randf_range(0.2, 0.85) * vs.y)
				e = InputEventScreenTouch.new()
				e.pressed = true
			1, 2, 3, 4, 5:
				e = InputEventScreenDrag.new()
				var d := Vector2(randf_range(-60, 60), randf_range(-60, 60))
				e.relative = d
				p += d
			6:
				e = InputEventScreenTouch.new()
				e.pressed = false
			_:
				continue
		e.index = 0
		e.position = p
		Input.parse_input_event(e)
	print("POKE_DONE")
	get_tree().quit()


func _resize() -> void:
	var s := get_viewport().get_visible_rect().size
	wipe_rect.size = s
	wipe_mat.set_shader_parameter("size", s)


func _show(n: String, a) -> void:
	if cur:
		cur.queue_free()
	var path := "res://scripts/%s.gd" % SCREENS.get(n, "title")
	if not ResourceLoader.exists(path):
		path = "res://scripts/title.gd"
	var s = load(path).new()
	s.arg = a
	cur = s
	add_child(s)
	move_child(s, 0)


func go(n: String, a = null) -> void:
	if busy:
		return
	busy = true
	G.play("whoosh", 1.2, -6.0)
	var tw := create_tween()
	tw.tween_method(func(v): wipe_mat.set_shader_parameter("r", v), 0.0, 1.0, 0.25).set_ease(Tween.EASE_IN).set_trans(Tween.TRANS_QUAD)
	tw.tween_callback(func(): _show(n, a))
	tw.tween_interval(0.05)
	tw.tween_method(func(v): wipe_mat.set_shader_parameter("r", v), 1.0, 0.0, 0.3).set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_QUAD)
	tw.tween_callback(func():
		wipe_mat.set_shader_parameter("r", 2.0)
		busy = false)

