	cam.position = pos
	cam.look_at(target, Vector3.UP)
	cam_base = cam.transform


func win(msg := "") -> void:
	if result == 0:
		result = 1
		if msg != "":
			fx.text(Vector2(W * 0.5, H * 0.32), msg, G.LIME, 76 * U)


var why := ""


func lose(msg := "") -> void:
	if result == 0:
		result = -1
		why = msg
		if msg != "":
			fx.text(Vector2(W * 0.5, H * 0.32), msg, G.RED, 70 * U)


## called by the runner when the fuse runs out
func timeout() -> void:
	if survive:
		win()
	else:
		lose("TOO SLOW!")


func shake(a: float) -> void:
	shake_amt = maxf(shake_amt, a)


func step(dt: float) -> void:
	t += dt
	if result != 0:
		rt += dt
	tick(dt)
	fx.update(dt)
	shake_amt = maxf(0.0, shake_amt - dt * 2.5)
	if shake_amt > 0.0:
		cam.h_offset = randf_range(-1, 1) * shake_amt * 0.3
		cam.v_offset = randf_range(-1, 1) * shake_amt * 0.3
	else:
		cam.h_offset = 0.0
		cam.v_offset = 0.0


# ---- geometry helpers
func spos(w: Vector3) -> Vector2:
	return cam.unproject_position(w)


func ray_o(p: Vector2) -> Vector3:
	return cam.project_ray_origin(p)


func ray_d(p: Vector2) -> Vector3:
	return cam.project_ray_normal(p)


func hit_sphere(p: Vector2, c: Vector3, r: float) -> bool:
	## true when the tap ray passes within r of c (generous for fingers)
	var o := ray_o(p)
	var d := ray_d(p)
	var t0 := (c - o).dot(d)
	if t0 < 0.0:
		return false
	return (o + d * t0).distance_to(c) <= r


func ray_dist(p: Vector2, c: Vector3) -> float:
	var o := ray_o(p)
	var d := ray_d(p)
	var t0 := maxf(0.0, (c - o).dot(d))
	return (o + d * t0).distance_to(c)


func plane_y(p: Vector2, y := 0.0) -> Vector3:
	var o := ray_o(p)
	var d := ray_d(p)
	if absf(d.y) < 0.0001:
		return o
	var k := (y - o.y) / d.y
	return o + d * maxf(k, 0.0)


func plane_z(p: Vector2, z := 0.0) -> Vector3:
	var o := ray_o(p)
	var d := ray_d(p)
	if absf(d.z) < 0.0001:
		return o
	var k := (z - o.z) / d.z
	return o + d * maxf(k, 0.0)


func boom(pos: Vector3, size := 1.0, col := Color("ff7a1a"), debris := Color("4a4e5e"), snd := "boom") -> void:
	K.boom(self, pos, size, col, debris)
	G.play(snd, randf_range(0.9, 1.1))
	shake(0.6 * size)

