extends RefCounted
## 2D HUD particles: shards, rings and popup text.

enum { DOT, SHARD, TEXT, RING }

var ps: Array = []
var grav := 900.0


func add(p: Vector2, v: Vector2, life: float, col: Color, size: float, kind := DOT, txt := "") -> Dictionary:
	var q := {p = p, v = v, life = life, max = life, col = col, size = size, kind = kind, rot = randf() * TAU,
		vr = randf_range(-8.0, 8.0), txt = txt, g = 1.0}
	ps.append(q)
	return q


func burst(p: Vector2, col: Color, n := 16, sp := 420.0, size := 7.0) -> void:
	for i in n:
		var a := randf() * TAU
		add(p, Vector2(cos(a), sin(a)) * sp * randf_range(0.35, 1.0), randf_range(0.3, 0.6), col, size * randf_range(0.6, 1.3))


func shards(p: Vector2, n := 40, sp := 800.0) -> void:
	for i in n:
		var a := randf_range(-PI * 0.95, -PI * 0.05)
		var q := add(p, Vector2(cos(a), sin(a)) * sp * randf_range(0.4, 1.0), randf_range(0.9, 1.6), G.NEON[randi() % 6], randf_range(10, 18), SHARD)
		q.g = 0.6


func rain(w: float, n := 80) -> void:
	for i in n:
		var q := add(Vector2(randf() * w, randf_range(-300, -20)), Vector2(randf_range(-60, 60), randf_range(150, 380)), randf_range(2.0, 3.0), G.NEON[randi() % 6], randf_range(10, 16), SHARD)
		q.g = 0.2


func ring(p: Vector2, col: Color, r := 40.0) -> void:
	add(p, Vector2.ZERO, 0.4, col, r, RING)


func text(p: Vector2, s: String, col := Color.WHITE, size := 52.0) -> void:
	var q := add(p, Vector2(0, -140), 0.85, col, size, TEXT, s)
	q.g = 0.0


func update(dt: float) -> void:
	var i := ps.size() - 1
	while i >= 0:
		var q: Dictionary = ps[i]
		q.life -= dt
		if q.life <= 0.0:
			ps.remove_at(i)
		else:
			q.v.y += grav * q.g * dt
			if q.kind == SHARD:
				q.v *= 1.0 - 1.5 * dt
			q.p += q.v * dt
			q.rot += q.vr * dt
		i -= 1


func draw(ci: CanvasItem) -> void:
	for q in ps:
		var f: float = q.life / q.max
		var col: Color = q.col
		match q.kind:
			DOT:
				ci.draw_circle(q.p, q.size * (0.4 + 0.6 * f), Color(col, minf(1.0, f * 2.0)), true, -1.0, true)
			SHARD:
				var d: Vector2 = Vector2(cos(q.rot), sin(q.rot)) * q.size * 0.6
				var e: Vector2 = Vector2(-d.y, d.x) * 0.3
				ci.draw_colored_polygon(PackedVector2Array([q.p - d, q.p + e, q.p + d, q.p - e * 0.5]), Color(col, minf(1.0, f * 3.0)))
			RING:
				ci.draw_arc(q.p, q.size * (1.0 + (1.0 - f) * 1.8), 0, TAU, 40, Color(col, f), 6.0 * f + 1.0, true)
			TEXT:
				var sc: float = 1.0 + 0.35 * maxf(0.0, (f - 0.8) / 0.2)
				G.txt(ci, q.p, q.txt, int(q.size * sc), Color(col, minf(1.0, f * 3.0)), int(q.size * 0.14), null, HORIZONTAL_ALIGNMENT_CENTER, Color(G.INK, minf(1.0, f * 3.0)), 1.0)

