extends Node3D
## Base class for every full-screen page: a 3D world plus a HUD layer with neon buttons.

const Parts = preload("res://scripts/parts.gd")

var W := 1200.0
var H := 900.0
var U := 1.0
var T := 0.0
var portrait := false
var arg = null
var hud_layer: CanvasLayer
var hud: Node2D
var buttons: Array = []
var fx := Parts.new()
var held := {}
var cam: Camera3D
var shake_amt := 0.0


func _ready() -> void:
	hud_layer = CanvasLayer.new()
	hud_layer.layer = 5
	add_child(hud_layer)
	hud = Node2D.new()
	hud_layer.add_child(hud)
	hud.draw.connect(_draw_hud)
	_measure()
	get_viewport().size_changed.connect(_on_resize)
	setup()
	layout()


func _on_resize() -> void:
	_measure()
	layout()


func _measure() -> void:
	var s := get_viewport().get_visible_rect().size
	W = s.x
	H = s.y
	U = minf(W, H) / 900.0
	portrait = H > W * 1.05


# ---- override points
func setup() -> void:
	pass


func layout() -> void:
	pass


func update(_dt: float) -> void:
	pass


func paint() -> void:
	pass


func paint_top() -> void:
	pass


func down(_p: Vector2, _i: int) -> void:
	pass


func drag(_p: Vector2, _i: int, _rel: Vector2) -> void:
	pass


func up(_p: Vector2, _i: int) -> void:
	pass


func back() -> void:
	G.main.go("title")


func shake(a: float) -> void:
	shake_amt = maxf(shake_amt, a)


# ---- loop
func _process(dt: float) -> void:
	dt = minf(dt, 0.05)
	T += dt
	for b in buttons:
		b.press = move_toward(b.press, 1.0 if b.down else 0.0, dt * 12.0)
		b.pop = maxf(0.0, b.pop - dt * 3.0)
	update(dt)
	fx.update(dt)
	if cam:
		shake_amt = maxf(0.0, shake_amt - dt * 2.5)
		cam.h_offset = randf_range(-1, 1) * shake_amt * 0.25
		cam.v_offset = randf_range(-1, 1) * shake_amt * 0.25
	hud.queue_redraw()


func _draw_hud() -> void:
	paint()
	for b in buttons:
		if b.visible:
			draw_button(b)
	fx.draw(hud)
	paint_top()


func _input(e: InputEvent) -> void:
	if G.main and G.main.busy:
		return
	if e is InputEventScreenTouch:
		var p: Vector2 = e.position
		if e.pressed:
			var hit = button_at(p)
			if hit != null:
				hit.down = true
				held[e.index] = hit
				G.play("click", 1.0, -4.0)
				return
			down(p, e.index)
		else:
			if held.has(e.index):
				var b = held[e.index]
				held.erase(e.index)
				b.down = false
				if b.visible and b.rect.grow(20).has_point(p):
					b.pop = 1.0
					G.play("select")
					b.cb.call()
				return
			up(p, e.index)
	elif e is InputEventScreenDrag:
		if held.has(e.index):
			return
		drag(e.position, e.index, e.relative)


func button_at(p: Vector2):
	for i in range(buttons.size() - 1, -1, -1):
		var b = buttons[i]
		if b.visible and b.enabled and b.rect.has_point(p):
			return b
	return null


# ---- buttons
func add_button(text: String, col: Color, cb: Callable, size := 44, icon := "") -> Dictionary:
	var b := {text = text, col = col, cb = cb, size = size, rect = Rect2(), down = false, press = 0.0, pop = 0.0,
		visible = true, enabled = true, icon = icon, sub = "", big = false, tag = ""}
	buttons.append(b)
	return b


func add_back(cb := Callable()) -> Dictionary:
	return add_button("", G.WHITE, cb if cb.is_valid() else back, 40, "back")


func place_back(b: Dictionary) -> void:
	b.rect = Rect2(Vector2(22, 22) * U, Vector2(88, 88) * U)


func draw_button(b: Dictionary) -> void:
	var ci := hud
	var r: Rect2 = b.rect
	var c := r.get_center()
	var k: float = 1.0 - 0.04 * b.press + sin(b.pop * PI) * 0.04
	var rr := Rect2(c + (r.position - c) * k, r.size * k)
	var col: Color = b.col if b.enabled else G.STEEL
	var cut := minf(rr.size.y * 0.32, 26.0 * U)
	if b.big:
		G.glow_rect(ci, rr, cut, col, 4.0 * U * (1.0 + 0.3 * sin(T * 4.0)))
	G.chamfer(ci, Rect2(rr.position + Vector2(0, 6 * U), rr.size), cut, Color(0, 0, 0, 0.45))
	var fill := G.PANEL.lerp(Color(col, 0.9), 0.18 + 0.5 * b.press)
	if b.big:
		fill = Color(col, 0.85).lerp(Color.WHITE, 0.15 * b.press)
	G.chamfer(ci, rr, cut, fill, col, 3.0 * U)
	# accent tick on the left edge
	if not b.big and b.icon == "":
		ci.draw_rect(Rect2(rr.position + Vector2(10 * U, rr.size.y * 0.25), Vector2(5 * U, rr.size.y * 0.5)), col)
	var tc := rr.get_center()
	var tcol := G.INK if b.big else G.WHITE
	if b.icon != "":
		draw_icon(b.icon, tc, rr.size.y * 0.3, col)
	elif b.sub != "":
		G.txt(ci, tc - Vector2(0, rr.size.y * 0.13), b.text, int(b.size * U), tcol, 0)
		G.txt(ci, tc + Vector2(0, rr.size.y * 0.24), b.sub, int(b.size * U * 0.42), Color(tcol, 0.8), 0, G.font_body)
	elif "\n" in b.text:
		var ls: PackedStringArray = b.text.split("\n")
		var lh: float = b.size * U * 1.0
		for i in ls.size():
			G.txt(ci, tc + Vector2(0, (i - (ls.size() - 1) * 0.5) * lh), ls[i], int(b.size * U), tcol, 0)
	else:
		G.txt(ci, tc, b.text, int(b.size * U), tcol, 0)


func draw_icon(kind: String, c: Vector2, s: float, col: Color) -> void:
	var ci := hud
	match kind:
		"back":
			ci.draw_polyline(PackedVector2Array([c + Vector2(0.15 * s, -0.75 * s), c + Vector2(-0.6 * s, 0), c + Vector2(0.15 * s, 0.75 * s)]), G.WHITE, 0.24 * s, true)
			ci.draw_line(c + Vector2(-0.5 * s, 0), c + Vector2(0.8 * s, 0), G.WHITE, 0.24 * s, true)
		"pause":
			ci.draw_rect(Rect2(c + Vector2(-0.55 * s, -0.7 * s), Vector2(0.38 * s, 1.4 * s)), G.WHITE)
			ci.draw_rect(Rect2(c + Vector2(0.17 * s, -0.7 * s), Vector2(0.38 * s, 1.4 * s)), G.WHITE)
		"sound":
			var body := PackedVector2Array([c + Vector2(-0.85 * s, -0.3 * s), c + Vector2(-0.4 * s, -0.3 * s), c + Vector2(0.15 * s, -0.8 * s),
				c + Vector2(0.15 * s, 0.8 * s), c + Vector2(-0.4 * s, 0.3 * s), c + Vector2(-0.85 * s, 0.3 * s)])
			ci.draw_colored_polygon(body, G.WHITE)
			if G.data.sound:
				ci.draw_arc(c + Vector2(0.2 * s, 0), 0.45 * s, -0.9, 0.9, 12, G.WHITE, 0.14 * s, true)
				ci.draw_arc(c + Vector2(0.2 * s, 0), 0.8 * s, -0.9, 0.9, 12, G.WHITE, 0.14 * s, true)
			else:
				ci.draw_line(c + Vector2(0.35 * s, -0.4 * s), c + Vector2(0.95 * s, 0.4 * s), G.RED, 0.18 * s, true)
				ci.draw_line(c + Vector2(0.95 * s, -0.4 * s), c + Vector2(0.35 * s, 0.4 * s), G.RED, 0.18 * s, true)
		"music":
			ci.draw_line(c + Vector2(-0.35 * s, 0.55 * s), c + Vector2(-0.35 * s, -0.75 * s), G.WHITE, 0.14 * s, true)
			ci.draw_line(c + Vector2(0.55 * s, 0.35 * s), c + Vector2(0.55 * s, -0.95 * s), G.WHITE, 0.14 * s, true)
			ci.draw_line(c + Vector2(-0.35 * s, -0.75 * s), c + Vector2(0.55 * s, -0.95 * s), G.WHITE, 0.26 * s, true)
			ci.draw_circle(c + Vector2(-0.55 * s, 0.6 * s), 0.26 * s, G.WHITE, true, -1.0, true)
			ci.draw_circle(c + Vector2(0.35 * s, 0.4 * s), 0.26 * s, G.WHITE, true, -1.0, true)
			if not G.data.music:
				ci.draw_line(c + Vector2(-0.9 * s, -0.9 * s), c + Vector2(0.9 * s, 0.9 * s), G.RED, 0.18 * s, true)
		"retry":
			ci.draw_arc(c, 0.65 * s, 0.6, TAU - 0.3, 24, G.WHITE, 0.22 * s, true)
			var tip := c + Vector2(cos(0.6), sin(0.6)) * 0.65 * s
			ci.draw_colored_polygon(PackedVector2Array([tip + Vector2(-0.4 * s, 0.05 * s), tip + Vector2(0.35 * s, -0.25 * s), tip + Vector2(0.2 * s, 0.45 * s)]), G.WHITE)


func title_text(pos: Vector2, s: String, size: float, col := G.WHITE, glow_col := G.CYAN) -> void:
	var sz := int(size * U)
	G.txt(hud, pos, s, sz, col, 0, G.font_title, HORIZONTAL_ALIGNMENT_CENTER, G.INK, 0.0)
	G.txt(hud, pos, s, sz, Color(glow_col, 0.0), 0, G.font_title, HORIZONTAL_ALIGNMENT_CENTER, G.INK, 1.2)
	G.txt(hud, pos, s, sz, col, 0, G.font_title)

