extends Node
## Headless self-test: bots play every micro-game at each level and speed.

func _ready() -> void:
	var blitz = load("res://scripts/blitz.gd")
	var names: Array = blitz.MICROS.keys()
	var only := ""
	for a in OS.get_cmdline_user_args():
		if a.begins_with("--only="):
			only = a.substr(7)
	var report := []
	var fails := 0
	for n in names + ["BOSS"]:
		if only != "" and n != only:
			continue
		var line := "%-8s" % n
		for lvl in [1, 2, 3]:
			for sp in [1.0, 1.9]:
				var wins := 0
				var runs := 3
				for r in runs:
					var scr: GDScript = blitz.BOSS if n == "BOSS" else blitz.MICROS[n]
					var m = scr.new()
					add_child(m)
					m.init(1200, 900, lvl)
					m.cam.make_current()
					var dt := 1.0 / 60.0
					var steps := 0
					while m.result == 0 and m.t < m.dur and steps < 3000:
						m.auto(dt * sp)
						m.step(dt * sp)
						steps += 1
					if m.result == 0:
						m.timeout()
					if m.result > 0:
						wins += 1
					elif only != "":
						print("  lost L%d: %s t=%.1f" % [lvl, m.why, m.t])
					m.free()
				line += " L%d@%.1f:%d/%d" % [lvl, sp, wins, runs]
				if wins < runs:
					fails += 1
		report.append(line)
	for l in report:
		print(l)
	print("SELFTEST_DONE fails=%d" % fails)
	get_tree().quit()

