extends "res://scripts/micro3d.gd"

var gun: Node3D
var muzzle: Node3D
var flash: MeshInstance3D
var targets: Array = []
var need := 4
var got := 0
var recoil := 0.0
var spawned := 0


func setup() -> void:
	word = "BLAST!"
	hint = "Shoot down the gray drones!"
	dur = 6.0
	accent = G.CYAN
	world("space", false)
	place_cam(Vector3.ZERO, Vector3(0, 0, -10), 65)
	need = 3 + lvl
	var planet := K.sphere(self, 45.0, Vector3(40, -32, -130), K.mat(Color("3b2a8a"), 0.0, 0.8), 48)
	planet.rotation.z = 0.3
	K.torus(self, 55.0, 62.0, Vector3(40, -32, -130), K.unlit(Color(0.6, 0.5, 1.0, 0.25), true), 64).rotation_degrees = Vector3(70, 0, 20)
	K.sphere(self, 6.0, Vector3(-38, 18, -110), K.mat(Color("8c8fa3"), 0.0, 0.9), 24)
	for i in 14:
		var r := K.sphere(self, randf_range(0.4, 1.4), Vector3(randf_range(-30, 30), randf_range(-14, 14), randf_range(-60, -30)), K.mat(Color("4a4448"), 0.1, 0.95), 8)
		r.scale = Vector3(1.0, randf_range(0.6, 1.0), randf_range(0.7, 1.2))
	# gun attached to the camera
	gun = Node3D.new()
	cam.add_child(gun)
	gun.position = Vector3(0.85, -0.75, -1.5)
	var body := K.mat(Color("1d2030"), 0.9, 0.3)
	K.box(gun, Vector3(0.36, 0.3, 1.2), Vector3(0, 0, 0), body)
	for sx in [-0.09, 0.09]:
		var b := K.cyl(gun, 0.05, 0.05, 0.9, Vector3(sx, 0.04, -0.85), body, 10)
		b.rotation.x = PI / 2
	K.box(gun, Vector3(0.06, 0.03, 0.9), Vector3(0.12, 0.16, 0.05), K.neon(G.CYAN, 1.6))
	K.box(gun, Vector3(0.06, 0.03, 0.9), Vector3(-0.12, 0.16, 0.05), K.neon(G.CYAN, 1.6))
	muzzle = Node3D.new()
	gun.add_child(muzzle)
	muzzle.position = Vector3(0, 0.04, -1.35)
	flash = K.sphere(muzzle, 0.18, Vector3.ZERO, K.neon(Color(0.6, 1, 1), 8.0), 10)
	flash.visible = false
	for i in mini(need, 3):
		spawn()


func spawn() -> void:
	var n := Node3D.new()
	add_child(n)
	var gray := K.mat(Color("6d7385"), 0.8, 0.35)
	K.sphere(n, 0.8, Vector3.ZERO, gray, 18)
	for k in 6:
		var dirs := [Vector3.RIGHT, Vector3.LEFT, Vector3.UP, Vector3.DOWN, Vector3.FORWARD, Vector3.BACK]
		var d: Vector3 = dirs[k]
		var sp := K.cyl(n, 0.0, 0.18, 0.6, d * 0.95, K.mat(Color("3a3e4c"), 0.8, 0.4), 8)
		sp.look_at_from_position(d * 0.95, d * 2.0, Vector3.UP if absf(d.y) < 0.9 else Vector3.RIGHT)
		sp.rotate_object_local(Vector3.RIGHT, -PI / 2)
	K.sphere(n, 0.28, Vector3(0, 0, 0.62), K.neon(G.RED, 6.0), 12)
	var z := randf_range(-13.0, -20.0)
	targets.append({n = n, alive = true, z = z, ph = randf() * TAU, sp = randf_range(0.7, 1.1) * (0.8 + lvl * 0.35),
		ax = randf_range(5.0, 8.0), ay = randf_range(2.0, 3.6)})
	spawned += 1
	n.position = pos_of(targets[targets.size() - 1])


func pos_of(tg: Dictionary) -> Vector3:
	var a: float = t * tg.sp + tg.ph
	return Vector3(sin(a) * tg.ax, sin(a * 1.7 + 1.0) * tg.ay, tg.z)


func tick(dt: float) -> void:
	recoil = maxf(0.0, recoil - dt * 6.0)
	gun.position = Vector3(0.85, -0.75, -1.5 + recoil * 0.25)
	flash.visible = recoil > 0.6
	for tg in targets:
		if tg.alive:
			var n: Node3D = tg.n
			n.position = pos_of(tg)
			n.look_at(Vector3.ZERO, Vector3.UP)
			n.rotate_object_local(Vector3.UP, PI)


func down(p: Vector2, _i: int) -> void:
	if result != 0:
		return
	recoil = 1.0
	G.play("laser", randf_range(0.95, 1.1))
	var best = null
	var bd := 1.5
	for tg in targets:
		if tg.alive:
			var d := ray_dist(p, (tg.n as Node3D).position)
			if d < bd:
				bd = d
				best = tg
	var from := muzzle.global_position
	if best == null:
		K.beam(self, from, ray_o(p) + ray_d(p) * 40.0, G.CYAN, 0.05)
		return
	var c: Vector3 = (best.n as Node3D).position
	K.beam(self, from, c, G.CYAN, 0.06)
	best.alive = false
	(best.n as Node3D).queue_free()
	boom(c, 0.9, Color("4fd8ff"), Color("6d7385"), "boom_s")
	got += 1
	fx.text(spos(c) - Vector2(0, 40 * U), "DOWN!", G.CYAN, 46 * U)
	if got >= need:
		win("ALL CLEAR!")
	elif spawned < need:
		spawn()


func auto(_dt: float) -> void:
	if int(t * 60) % 14 == 0:
		for tg in targets:
			if tg.alive:
				down(spos((tg.n as Node3D).position), 0)
				return


func paint2d(ci: CanvasItem) -> void:
	for tg in targets:
		if tg.alive:
			var c := spos((tg.n as Node3D).position)
			G.brackets(ci, c, 44 * U, Color(G.RED, 0.9), 3 * U, -t * 2.0)
	G.txt(ci, Vector2(W - 40 * U, 150 * U), "%d / %d" % [got, need], int(44 * U), G.WHITE, int(6 * U), null, HORIZONTAL_ALIGNMENT_RIGHT)

