extends "res://scripts/micro3d.gd"
## BOSS: the GRAYLORD. Blast every red core, shoot down its missiles.

var lord: Node3D
var cores: Array = []
var missiles: Array = []
var shields := 3
var fire_t := 1.5
var spin := 0.5
var total := 5
var dying := 0.0
var hurt := 0.0
const CAMP := Vector3(0, 2.2, 10)


func setup() -> void:
	word = "BOSS!"
	hint = "Blast the GRAYLORD's red cores! Shoot its missiles!"
	dur = 12.0
	accent = G.RED
	world("storm", true, 40.0)
	place_cam(CAMP, Vector3(0, 4.2, -8), 60)
	K.ground(self, 200.0, G.RED, Color(0.03, 0.012, 0.02), 3.0, 1.5)
	K.city(self, Vector3(0, 0, -30), 24.0, 110.0, 140, 9, 8.0, 40.0)
	lord = K.graylord(self, 1.0)
	lord.position = Vector3(0, 4.6, -9)
	spin = 0.35 + lvl * 0.2
	total = 3 + lvl * 2
	var spots: Array[Vector3] = []
	var faces := [Vector3.BACK, Vector3.RIGHT, Vector3.LEFT, Vector3.FORWARD]
	for f in faces:
		var u: Vector3 = Vector3.UP if absf(f.y) < 0.5 else Vector3.RIGHT
		var v: Vector3 = f.cross(u)
		for k in 4:
			var off: Vector3 = u * (0.9 if k < 2 else -0.9) + v * (0.9 if k % 2 == 0 else -0.9)
			spots.append(f * 2.12 + off)
	spots.shuffle()
	# make sure the first few cores sit on the face looking at the camera
	spots.sort_custom(func(a, b): return a.z > b.z)
	var chosen := spots.slice(0, 2)
	var rest := spots.slice(2)
	rest.shuffle()
	chosen.append_array(rest.slice(0, total - 2))
	for p in chosen:
		var holder := Node3D.new()
		lord.add_child(holder)
		holder.position = p
		var m := StandardMaterial3D.new()
		m.albedo_color = Color(0.3, 0.0, 0.02)
		m.emission_enabled = true
		m.emission = Color("ff1f3d")
		m.emission_energy_multiplier = 5.0
		K.sphere(holder, 0.38, Vector3.ZERO, m, 16)
		var rim := K.torus(holder, 0.4, 0.55, Vector3.ZERO, K.mat(Color("2b2e3a"), 0.9, 0.3), 20)
		rim.quaternion = Quaternion(Vector3.UP, p.normalized())
		cores.append({n = holder, m = m, alive = true, normal = p.normalized()})


func core_pos(c: Dictionary) -> Vector3:
	return (c.n as Node3D).global_position


func facing(c: Dictionary) -> bool:
	var nrm: Vector3 = lord.global_transform.basis * (c.normal as Vector3)
	return nrm.dot((CAMP - core_pos(c)).normalized()) > 0.15


func alive_count() -> int:
	var n := 0
	for c in cores:
		if c.alive:
			n += 1
	return n


func tick(dt: float) -> void:
	hurt = maxf(0.0, hurt - dt * 2.0)
	if dying > 0.0:
		dying += dt
		lord.position.y -= dt * dt * 30.0 + dt * 1.5
		lord.rotation.z += dt * 0.8
		if fmod(dying, 0.18) < dt:
			K.boom(self, lord.position + Vector3(randf_range(-2, 2), randf_range(-2, 2), randf_range(-1, 2)), randf_range(1.0, 1.8))
			G.play("boom", randf_range(0.8, 1.1), -3.0)
			shake(0.6)
		return
	lord.rotation.y += dt * spin
	lord.rotation.x = sin(t * 0.7) * 0.25
	lord.position = Vector3(sin(t * 0.6) * 2.0, 4.6 + sin(t * 1.3) * 0.5, -9)
	var rings: Array = lord.get_meta("rings")
	(rings[0] as Node3D).rotate_object_local(Vector3.UP, dt * 2.0)
	(rings[1] as Node3D).rotate_object_local(Vector3.UP, -dt * 1.4)
	for c in cores:
		if c.alive:
			(c.m as StandardMaterial3D).emission_energy_multiplier = 4.0 + sin(t * 8.0) * 2.0
	if result == 0:
		fire_t -= dt
		if fire_t <= 0.0:
			fire_t = 2.4 - lvl * 0.35
			fire()
	var i := missiles.size() - 1
	while i >= 0:
		var m: Dictionary = missiles[i]
		m.f += dt / m.time
		var p: Vector3 = (m.a as Vector3).lerp(m.b, m.f) + Vector3(0, sin(m.f * PI) * 2.5, 0)
		(m.n as Node3D).position = p
		(m.n as Node3D).look_at(m.b, Vector3.UP)
		if m.f >= 1.0:
			(m.n as Node3D).queue_free()
			missiles.remove_at(i)
			if result == 0:
				shields -= 1
				hurt = 1.0
				shake(1.0)
				G.play("boom_s", 0.8)
				G.play("zap", 0.6)
				if shields <= 0:
					lose("SHIELDS DOWN!")
		i -= 1


func fire() -> void:
	var n := Node3D.new()
	add_child(n)
	K.sphere(n, 0.32, Vector3.ZERO, K.neon(Color("ff2a40"), 6.0), 12)
	var tail := K.cyl(n, 0.3, 0.0, 1.6, Vector3(0, 0, 0.9), K.unlit(Color(1, 0.3, 0.2, 0.4), true), 10)
	tail.rotation.x = PI / 2
	var a := lord.global_position + Vector3(0, 0.5, 2.2)
	var b := CAMP + Vector3(randf_range(-1.5, 1.5), randf_range(-1.0, 0.0), -1.5)
	n.position = a
	missiles.append({n = n, a = a, b = b, f = 0.0, time = 2.6 - lvl * 0.25})
	G.play("laser2", 0.6, -4.0)


func down(p: Vector2, _i: int) -> void:
	if result != 0 or dying > 0.0:
		return
	G.play("laser", randf_range(0.95, 1.1), -3.0)
	var gun := CAMP + Vector3(0.9, -0.8, -1.0)
	# missiles first
	for m in missiles:
		var mp: Vector3 = (m.n as Node3D).position
		if ray_dist(p, mp) < 0.9:
			K.beam(self, gun, mp, G.CYAN, 0.05)
			K.boom(self, mp, 0.6, Color("ff8a3a"))
			G.play("boom_s", 1.3, -4.0)
			(m.n as Node3D).queue_free()
			missiles.erase(m)
			fx.text(spos(mp), "INTERCEPT!", G.CYAN, 36 * U)
			return
	var best = null
	var bd := 0.85
	for c in cores:
		if c.alive and facing(c):
			var d := ray_dist(p, core_pos(c))
			if d < bd:
				bd = d
				best = c
	if best == null:
		K.beam(self, gun, ray_o(p) + ray_d(p) * 30.0, G.CYAN, 0.04)
		return
	var cp := core_pos(best)
	K.beam(self, gun, cp, G.CYAN, 0.06)
	best.alive = false
	(best.n as Node3D).visible = false
	boom(cp, 0.9, Color("ff3a4a"), Color("5d6273"), "boom_s")
	G.play("zap")
	fx.text(spos(cp) - Vector2(0, 40 * U), "CORE DOWN!", G.YELLOW, 40 * U)
	if alive_count() == 0:
		dying = 0.01
		for m in missiles:
			(m.n as Node3D).queue_free()
		missiles.clear()
		G.play("boom", 0.7)
		win("GRAYLORD DESTROYED!")


func auto(_dt: float) -> void:
	if int(t * 60) % 10 != 0:
		return
	for m in missiles:
		if m.f > 0.45:
			down(spos((m.n as Node3D).position), 0)
			return
	for c in cores:
		if c.alive and facing(c):
			down(spos(core_pos(c)), 0)
			return


func paint2d(ci: CanvasItem) -> void:
	var r := Rect2(W * 0.5 - 300 * U, 128 * U, 600 * U, 26 * U)
	G.txt(ci, Vector2(W * 0.5, 112 * U), "GRAYLORD", int(24 * U), G.RED, 0, G.font_title, HORIZONTAL_ALIGNMENT_CENTER, G.INK, 0.8)
	G.bar(ci, r, float(alive_count()) / float(total), G.RED)
	for k in 3:
		var c := Vector2(60 * U + k * 56 * U, H - 60 * U)
		var on := k < shields
		ci.draw_colored_polygon(PackedVector2Array([c + Vector2(0, -22) * U, c + Vector2(20, -12) * U, c + Vector2(16, 14) * U, c + Vector2(0, 24) * U, c + Vector2(-16, 14) * U, c + Vector2(-20, -12) * U]), Color(G.CYAN, 0.85) if on else Color(1, 1, 1, 0.12))
	G.txt(ci, Vector2(40 * U, H - 110 * U), "SHIELDS", int(20 * U), G.CYAN, 0, G.font_body, HORIZONTAL_ALIGNMENT_LEFT)
	for c in cores:
		if c.alive and facing(c):
			G.brackets(ci, spos(core_pos(c)), 34 * U, Color(G.YELLOW, 0.9), 3 * U, t * 2.0)
	for m in missiles:
		var mp := spos((m.n as Node3D).position)
		G.brackets(ci, mp, 30 * U, Color(G.CYAN, 0.9), 3 * U, -t * 3.0)
	if hurt > 0.0:
		ci.draw_rect(Rect2(0, 0, W, H), Color(1, 0.1, 0.15, hurt * 0.35))

