extends "res://scripts/micro3d.gd"

const PZ := -16.0
const LANE := 1.0
var ball: Node3D
var pins: Array = []
var rolling := false
var bx := 0.0
var bz := 0.0
var aim := 0.0
var need := 6
var evaluated := false
var down_count := 0


func setup() -> void:
	word = "BOWL!"
	hint = "Tap the lane to roll - knock the pins down!"
	accent = G.MAGENTA
	dur = 6.0
	need = 5 + lvl
	world("night", true, 30.0)
	place_cam(Vector3(0, 1.25, 2.4), Vector3(0, 0.1, PZ), 40)
	var wood := K.mat(Color("c48a4c"), 0.1, 0.25)
	K.box(self, Vector3(LANE * 2.0, 0.1, 24), Vector3(0, -0.05, -8), wood)
	for sx in [-1.0, 1.0]:
		K.box(self, Vector3(0.35, 0.06, 24), Vector3(sx * (LANE + 0.18), -0.1, -8), K.mat(Color("1b1e28"), 0.5, 0.4))
		K.box(self, Vector3(0.08, 0.08, 24), Vector3(sx * (LANE + 0.4), 0.0, -8), K.neon(G.MAGENTA, 4.0))
	for k in 7:
		K.prism(self, Vector3(0.12, 0.02, 0.2), Vector3((k - 3) * 0.24, 0.005, -4.0), K.neon(G.CYAN, 2.0)).rotation.x = -PI / 2
	K.box(self, Vector3(8, 4, 0.4), Vector3(0, 2, PZ - 1.6), K.mat(Color("101320"), 0.3, 0.6))
	K.box(self, Vector3(3.0, 0.15, 0.2), Vector3(0, 1.6, PZ - 1.3), K.neon(G.MAGENTA, 5.0))
	K.ground(self, 120.0, G.MAGENTA, Color(0.03, 0.015, 0.04), 2.0, 0.8, -0.2)
	for sx in [-1.0, 1.0]:
		for k in 4:
			var l := K.box(self, Vector3(0.2, 0.2, 2.0), Vector3(sx * 3.5, 2.5, -2.0 - k * 4.5), K.neon(G.NEON[k], 3.0))
			l.name = "Light"
	var key := SpotLight3D.new()
	key.position = Vector3(0, 5, PZ + 4)
	key.light_energy = 4.0
	key.spot_range = 10
	key.spot_angle = 35
	add_child(key)
	key.look_at(Vector3(0, 0, PZ), Vector3.UP)
	var rows := [[0.0], [-0.15, 0.15], [-0.3, 0.0, 0.3], [-0.45, -0.15, 0.15, 0.45]]
	for r in rows.size():
		for px in rows[r]:
			var p := Node3D.new()
			add_child(p)
			p.position = Vector3(px, 0, PZ - r * 0.26)
			var white := K.mat(Color("f2f2f6"), 0.1, 0.3)
			K.capsule(p, 0.06, 0.38, Vector3(0, 0.19, 0), white)
			K.sphere(p, 0.05, Vector3(0, 0.4, 0), white, 10)
			K.cyl(p, 0.052, 0.052, 0.03, Vector3(0, 0.3, 0), K.mat(G.RED, 0.2, 0.4), 10)
			pins.append({n = p, x = px, z = p.position.z, hit = false, t = 0.0, v = Vector3.ZERO, spin = Vector3.ZERO, delay = 0.0})
	ball = Node3D.new()
	add_child(ball)
	K.sphere(ball, 0.16, Vector3.ZERO, K.mat(Color("2a1460"), 0.3, 0.15), 20)
	K.sphere(ball, 0.17, Vector3.ZERO, K.unlit(Color(0.6, 0.2, 1.0, 0.3), true), 16)
	ball.position = Vector3(0, 0.16, 0.6)


func tick(dt: float) -> void:
	if rolling:
		bz -= 14.0 * dt
		var f := clampf((0.6 - bz) / (0.6 - PZ), 0.0, 1.0)
		var cx := lerpf(0.0, aim, f)
		ball.position = Vector3(cx, 0.16, bz)
		ball.rotation.x -= dt * 30.0
		if not evaluated and bz <= PZ + 0.15:
			evaluated = true
			strike_pins(cx)
		if bz < PZ - 2.0:
			rolling = false
			ball.visible = false
	for p in pins:
		if p.hit:
			p.delay -= dt
			if p.delay <= 0.0:
				p.t += dt
				var n: Node3D = p.n
				p.v.y -= 9.0 * dt
				n.position += p.v * dt
				if n.position.y < 0.0:
					n.position.y = 0.0
					p.v *= 0.6
					p.v.y = absf(p.v.y) * 0.3
				n.rotation += p.spin * dt * maxf(0.0, 1.0 - p.t * 0.8)
	if evaluated and result == 0 and t > 0.0:
		var settled := true
		for p in pins:
			if p.hit and p.t < 0.6:
				settled = false
		if settled:
			if down_count >= 10:
				win("STRIKE!")
			elif down_count >= need:
				win("%d PINS!" % down_count)
			else:
				lose("ONLY %d PINS" % down_count)


func timeout() -> void:
	if evaluated and down_count >= need:
		win("%d PINS!" % down_count)
	else:
		lose("TOO SLOW!" if not rolling and not evaluated else "ONLY %d PINS" % down_count)


func strike_pins(cx: float) -> void:
	var hits: Array = []
	for p in pins:
		if absf(p.x - cx) < 0.24:
			hits.append(p)
	# chain reaction: knocked pins topple their neighbours behind them
	var frontier := hits.duplicate()
	var guard := 0
	while frontier.size() > 0 and guard < 50:
		guard += 1
		var q: Dictionary = frontier.pop_front()
		for p in pins:
			if p in hits:
				continue
			var dzz: float = q.z - p.z
			var dxx: float = absf(p.x - q.x)
			if dzz > 0.05 and dzz < 0.6 and dxx < 0.36 and randf() < 0.85:
				hits.append(p)
				frontier.append(p)
	for p in hits:
		p.hit = true
		p.delay = (p.z - PZ) * -0.15
		var away: float = sign(p.x - cx) if absf(p.x - cx) > 0.02 else randf_range(-1, 1)
		p.v = Vector3(away * randf_range(0.8, 2.0), randf_range(1.0, 2.5), -randf_range(1.5, 3.5))
		p.spin = Vector3(randf_range(-9, -5), randf_range(-4, 4), away * randf_range(3, 8))
	down_count = hits.size()
	if hits.size() > 0:
		G.play("crunch", 1.4)
		G.play("clank", 1.6, -6.0)
		shake(0.25)
	else:
		G.play("thud")


func down(p: Vector2, _i: int) -> void:
	if rolling or evaluated or result != 0:
		return
	var g := plane_y(p, 0.0)
	var k := (0.6 - PZ) / maxf(0.6 - g.z, 0.5)
	aim = clampf(g.x * k, -LANE * 0.9, LANE * 0.9)
	rolling = true
	bz = 0.6
	G.play("whoosh", 0.6)
	G.play("thud", 0.5, -4.0)


func auto(_dt: float) -> void:
	if not rolling and not evaluated and t > 0.3:
		down(spos(Vector3(0.05, 0, PZ)), 0)


func paint2d(ci: CanvasItem) -> void:
	G.txt(ci, Vector2(W - 40 * U, 150 * U), "NEED %d" % need, int(34 * U), G.WHITE, int(5 * U), null, HORIZONTAL_ALIGNMENT_RIGHT)
	if not rolling and not evaluated:
		var a := spos(Vector3(-LANE, 0, -2))
		var b := spos(Vector3(LANE, 0, -2))
		ci.draw_line(a, b, Color(G.MAGENTA, 0.5 + 0.3 * sin(t * 6)), 4 * U, true)

files.scripts/micro/catch.gd:
extends "res://scripts/micro3d.gd"

var drone: Node3D
var x := 0.0
var tx := 0.0
var cores: Array = []
var caught := 0
var need := 3
const LANE := 6.0


func setup() -> void:
	word = "CATCH!"
	hint = "Slide under the energy cores and catch them!"
	accent = G.LIME
	dur = 6.0
	world("night", true, 30.0)
	place_cam(Vector3(0, 4.5, 11.0), Vector3(0, 3.0, 0), 60)
	K.ground(self, 200.0, G.LIME, Color(0.03, 0.03, 0.03), 2.0, 1.4)
	K.city(self, Vector3(0, 0, -30), 18.0, 120.0, 140, 71, 6.0, 30.0, 12.0)
	K.box(self, Vector3(14, 0.3, 3), Vector3(0, 0.15, 0), K.mat(Color("1b1e28"), 0.5, 0.4))
	K.box(self, Vector3(14.1, 0.06, 0.1), Vector3(0, 0.32, 1.5), K.neon(G.LIME, 3.0))
	drone = K.drone(self, G.LIME)
	drone.scale = Vector3.ONE * 1.3
	var ring := K.torus(drone, 0.75, 0.85, Vector3(0, -0.45, 0), K.neon(G.LIME, 4.0), 24)
	ring.name = "Net"
	need = 2 + lvl
	for i in need:
		var cx := randf_range(-LANE, LANE)
		if i > 0:
			var prev: float = cores[i - 1].x
			cx = clampf(prev + randf_range(-5.5, 5.5), -LANE, LANE)
		cores.append(make_core(cx, 0.3 + i * (1.35 - lvl * 0.12)))


func make_core(cx: float, start: float) -> Dictionary:
	var n := Node3D.new()
	add_child(n)
	K.sphere(n, 0.32, Vector3.ZERO, K.neon(G.LIME, 6.0), 14)
	K.torus(n, 0.42, 0.48, Vector3.ZERO, K.neon(G.CYAN, 3.0), 20)
	n.position = Vector3(cx, 14.0, 0)
	n.visible = false
	return {n = n, x = cx, start = start, state = 0, y = 14.0}


func tick(dt: float) -> void:
	var nx := move_toward(x, tx, 15.0 * dt)
	drone.rotation.z = clampf((x - nx) / maxf(dt, 0.0001) * 0.03, -0.5, 0.5)
	x = nx
	drone.position = Vector3(x, 1.6 + sin(t * 3.0) * 0.06, 0)
	K.spin_rotors(drone, dt)
	for c in cores:
		var n: Node3D = c.n
		if c.state == 0 and t >= c.start:
			c.state = 1
			n.visible = true
		if c.state == 1:
			c.y -= (7.5 + lvl * 1.5) * dt
			n.position = Vector3(c.x, c.y, 0)
			n.rotate_y(dt * 4.0)
			if c.y < 2.2 and c.y > 1.2 and absf(c.x - x) < 1.1:
				c.state = 2
				n.visible = false
				caught += 1
				G.play("xp", 1.0 + caught * 0.12)
				K.sparks(self, n.position, G.LIME, 18, 5.0, 0.7)
				K.flash_ring(self, n.position, G.LIME, 1.2)
				fx.text(spos(n.position) - Vector2(0, 40 * U), "+1", G.LIME, 46 * U)
				if caught >= cores.size():
					win("FULL POWER!")
			elif c.y <= 0.3:
				c.state = 3
				n.visible = false
				boom(Vector3(c.x, 0.4, 0), 0.8, G.LIME, Color("2a2e3a"), "boom_s")
				lose("DROPPED ONE!")


func down(p: Vector2, i: int) -> void:
	drag(p, i, Vector2.ZERO)


func drag(p: Vector2, _i: int, _r: Vector2) -> void:
	tx = clampf(plane_z(p, 0.0).x, -LANE, LANE)


func auto(_dt: float) -> void:
	for c in cores:
		if c.state == 1:
			tx = c.x
			return
	for c in cores:
		if c.state == 0:
			tx = c.x
			return


func paint2d(ci: CanvasItem) -> void:
