extends "res://scripts/micro3d.gd"

var drone: Node3D
var x := 0.0
var tx := 0.0
var rocks: Array = []
var spawn := 0.2
var dead := false
const LANE := 5.5


func setup() -> void:
	word = "DODGE!"
	hint = "Slide left and right - don't get hit!"
	dur = 5.0
	survive = true
	accent = G.RED
	world("storm")
	place_cam(Vector3(0, 6.2, 9.5), Vector3(0, 0.4, -3.0), 58)
	K.ground(self, 200.0, G.RED, Color(0.03, 0.015, 0.02), 2.0, 1.2, -0.02)
	K.box(self, Vector3(13, 0.1, 120), Vector3(0, -0.04, -40), K.mat(Color("17181f"), 0.4, 0.6))
	for sx in [-1.0, 1.0]:
		K.box(self, Vector3(0.15, 0.12, 120), Vector3(sx * 6.5, 0.02, -40), K.neon(G.RED, 4.0))
	K.city(self, Vector3(0, 0, -40), 14.0, 90.0, 120, 5, 6.0, 34.0, 13.0)
	drone = K.drone(self, G.CYAN)
	drone.position = Vector3(0, 1.2, 0)


func tick(dt: float) -> void:
	if not dead:
		var nx := move_toward(x, tx, 16.0 * dt)
		drone.rotation.z = clampf((x - nx) / maxf(dt, 0.001) * 0.03, -0.5, 0.5)
		x = nx
		drone.position = Vector3(x, 1.2 + sin(t * 3.0) * 0.08, 0)
		K.spin_rotors(drone, dt)
	var fall := 1.15 - lvl * 0.1
	if result == 0 and t < dur - 0.3:
		spawn -= dt
		if spawn <= 0.0:
			spawn = 0.62 - lvl * 0.09
			var rx := randf_range(-LANE, LANE)
			if randf() < 0.35:
				rx = clampf(x + randf_range(-0.6, 0.6), -LANE, LANE)
			spawn_rock(rx, fall)
	var i := rocks.size() - 1
	while i >= 0:
		var r: Dictionary = rocks[i]
		r.f += dt / r.fall
		var tgt: Vector3 = r.tgt
		var p: Vector3 = r.start.lerp(tgt, minf(r.f, 1.0))
		(r.n as Node3D).position = p
		((r.n as Node3D).get_meta("rock") as Node3D).rotate_x(dt * 5.0)
		var mk: MeshInstance3D = r.mk
		mk.scale = Vector3.ONE * (1.4 - 0.6 * r.f)
		if r.f >= 1.0:
			(r.n as Node3D).queue_free()
			mk.queue_free()
			boom(tgt + Vector3(0, 0.3, 0), 1.1, Color("ff5a2a"), Color("3a2a26"), "boom_s")
			if not dead and result == 0 and absf(tgt.x - x) < 1.25:
				dead = true
				boom(drone.position, 1.3, G.CYAN, Color("1c1f2e"))
				drone.visible = false
				lose("HIT!")
			rocks.remove_at(i)
		i -= 1


func spawn_rock(rx: float, fall: float) -> void:
	var tgt := Vector3(rx, 0, 0)
	var start := tgt + Vector3(randf_range(-5, 5), 24, -20)
	var n := Node3D.new()
	add_child(n)
	var rock := Node3D.new()
	n.add_child(rock)
	var rm := K.sphere(rock, 0.75, Vector3.ZERO, K.mat(Color("2a1d18"), 0.1, 0.9), 10)
	rm.scale = Vector3(1.0, 0.85, 1.1)
	K.sphere(rock, 0.88, Vector3.ZERO, K.unlit(Color(1.0, 0.45, 0.1, 0.35), true), 12)
	var dir := (tgt - start).normalized()
	var tail := K.cyl(n, 0.05, 0.75, 5.0, Vector3.ZERO, K.unlit(Color(1.0, 0.5, 0.15, 0.3), true), 10)
	tail.look_at_from_position(-dir * 2.6, -dir * 6.0, Vector3.UP)
	tail.rotate_object_local(Vector3.RIGHT, -PI / 2)
	n.set_meta("rock", rock)
	n.position = start
	var mk := K.torus(self, 0.9, 1.1, tgt + Vector3(0, 0.05, 0), K.neon(G.RED, 4.0), 24)
	rocks.append({n = n, mk = mk, start = start, tgt = tgt, f = 0.0, fall = fall})


func down(p: Vector2, i: int) -> void:
	drag(p, i, Vector2.ZERO)


func drag(p: Vector2, _i: int, _r: Vector2) -> void:
	tx = clampf(plane_y(p, 1.2).x, -LANE, LANE)


func auto(_dt: float) -> void:
	var best := x
	var bs := -99999.0
	for k in 23:
		var cx := lerpf(-LANE, LANE, k / 22.0)
		var s := 99999.0
		for r in rocks:
			var left: float = (1.0 - r.f) * r.fall
			var reach := absf(cx - x) / 16.0
			var gap: float = absf(r.tgt.x - cx)
			if left < 0.9:
				var lo := minf(x, cx) - 1.3
				var hi := maxf(x, cx) + 1.3
				if r.tgt.x > lo and r.tgt.x < hi and left < reach + 0.05:
					gap = 0.0
				s = minf(s, gap)
		s -= absf(cx - x) * 0.05
		if s > bs:
			bs = s
			best = cx
	tx = best

