extends "res://scripts/micro3d.gd"

var car: Node3D
var x := 0.0
var tx := 0.0
var gates: Array = []
var sp := 26.0
var passed := 0
var props: Array = []
var grid: MeshInstance3D
const HALF := 4.2


func setup() -> void:
	word = "DRIFT!"
	hint = "Steer through every gate!"
	accent = G.YELLOW
	world("night", true, 30.0)
	place_cam(Vector3(0, 3.2, 7.0), Vector3(0, 0.6, -8.0), 60)
	sp = 24.0 + lvl * 4.0
	grid = K.ground(self, 260.0, G.CYAN, Color(0.02, 0.02, 0.04), 2.0, 1.4, -0.02)
	(grid.material_override as ShaderMaterial).set_shader_parameter("scroll", Vector2(0, sp / 2.0))
	K.box(self, Vector3(10, 0.1, 260), Vector3(0, 0.0, -100), K.mat(Color("15161f"), 0.4, 0.5))
	for sx in [-1.0, 1.0]:
		K.box(self, Vector3(0.15, 0.14, 260), Vector3(sx * 5.0, 0.06, -100), K.neon(G.MAGENTA, 4.0))
	K.city(self, Vector3(0, 0, -60), 16.0, 110.0, 160, 61, 6.0, 40.0, 14.0)
	for i in 10:
		var side := -1.0 if i % 2 == 0 else 1.0
		var lamp := Node3D.new()
		add_child(lamp)
		lamp.position = Vector3(side * 6.2, 0, -i * 13.0)
		K.cyl(lamp, 0.08, 0.1, 4.0, Vector3(0, 2.0, 0), K.mat(Color("2a2e3a"), 0.5, 0.4), 8)
		K.box(lamp, Vector3(1.2, 0.12, 0.3), Vector3(-side * 0.5, 4.0, 0), K.neon(Color("fff1d6"), 5.0))
		props.append(lamp)
	car = make_car()
	var n := 2 + lvl
	var z := -45.0
	var gx := 0.0
	for i in n:
		gx = clampf(gx + randf_range(-3.2, 3.2), -HALF + 1.2, HALF - 1.2)
		gates.append(make_gate(gx, z))
		z -= sp * randf_range(1.05, 1.3)
	dur = (-z) / sp - 0.4


func make_car() -> Node3D:
	var c := Node3D.new()
	add_child(c)
	var paint := K.mat(Color("ff2b55"), 0.6, 0.25)
	K.box(c, Vector3(1.7, 0.45, 3.6), Vector3(0, 0.5, 0), paint)
	K.box(c, Vector3(1.4, 0.4, 1.6), Vector3(0, 0.92, 0.2), K.mat(Color("0b0d14"), 0.8, 0.1))
	K.box(c, Vector3(1.8, 0.08, 0.5), Vector3(0, 0.95, 1.7), paint)
	for sx in [-1.0, 1.0]:
		for sz in [-1.0, 1.0]:
			var w := K.cyl(c, 0.34, 0.34, 0.3, Vector3(sx * 0.85, 0.34, sz * 1.15), K.mat(Color("101114"), 0.2, 0.7), 14)
			w.rotation.z = PI / 2
		K.box(c, Vector3(0.45, 0.12, 0.06), Vector3(sx * 0.55, 0.62, 1.81), K.neon(G.RED, 6.0))
		K.box(c, Vector3(0.4, 0.1, 0.06), Vector3(sx * 0.55, 0.6, -1.81), K.neon(Color("e8f4ff"), 5.0))
	K.box(c, Vector3(1.5, 0.04, 3.2), Vector3(0, 0.12, 0), K.unlit(Color(0.0, 0.9, 1.0, 0.6), true))
	var ug := OmniLight3D.new()
	ug.position = Vector3(0, 0.1, 0)
	ug.light_color = G.CYAN
	ug.light_energy = 2.0
	ug.omni_range = 3.0
	c.add_child(ug)
	return c


func make_gate(gx: float, z: float) -> Dictionary:
	var n := Node3D.new()
	add_child(n)
	n.position = Vector3(gx, 0, z)
	var post := K.mat(Color("23263a"), 0.5, 0.35)
	for sx in [-1.0, 1.0]:
		K.box(n, Vector3(0.3, 3.0, 0.3), Vector3(sx * 1.55, 1.5, 0), post)
		K.box(n, Vector3(0.34, 3.0, 0.08), Vector3(sx * 1.55, 1.5, 0.17), K.neon(G.YELLOW, 4.0))
	K.box(n, Vector3(3.4, 0.3, 0.3), Vector3(0, 3.0, 0), post)
	K.box(n, Vector3(3.4, 0.08, 0.34), Vector3(0, 3.0, 0.1), K.neon(G.YELLOW, 4.0))
	K.box(n, Vector3(2.8, 0.04, 0.6), Vector3(0, 0.07, 0), K.unlit(Color(1.0, 0.85, 0.1, 0.35), true))
	return {n = n, x = gx, done = false}


func tick(dt: float) -> void:
	var nx := move_toward(x, tx, 11.0 * dt)
	var steer := (nx - x) / maxf(dt, 0.0001)
	x = nx
	car.position = Vector3(x, 0, 0)
	car.rotation.y = clampf(-steer * 0.04, -0.4, 0.4)
	car.rotation.z = clampf(steer * 0.012, -0.12, 0.12)
	for g in gates:
		var n: Node3D = g.n
		n.position.z += sp * dt
		if not g.done and n.position.z >= 0.0:
			g.done = true
			if absf(x - g.x) < 1.3:
				passed += 1
				G.play("xp", 1.0 + passed * 0.1, -2.0)
				K.flash_ring(self, Vector3(g.x, 1.5, 0), G.YELLOW, 1.6, Vector3.BACK)
				if passed >= gates.size():
					win("CLEAN RUN!")
			elif result == 0:
				G.play("clank")
				shake(0.6)
				K.sparks(self, Vector3(x, 0.6, 0), G.YELLOW, 20, 6.0)
				lose("MISSED A GATE!")
	for p in props:
		p.position.z += sp * dt
		if p.position.z > 10.0:
			p.position.z -= 130.0


func timeout() -> void:
	if passed >= gates.size():
		win()
	else:
		lose("TOO SLOW!")


func down(p: Vector2, i: int) -> void:
	drag(p, i, Vector2.ZERO)


func drag(p: Vector2, _i: int, _r: Vector2) -> void:
	tx = clampf(plane_y(p, 0.5).x, -HALF, HALF)


func auto(_dt: float) -> void:
	for g in gates:
		if not g.done:
			tx = g.x
			return

