		K.box(self, Vector3(0.1, 0.02, 5.5), Vector3(sx * 4.25, 0.02, GZ + 2.75), line)
	# goal frame + net
	var post := K.mat(Color("f4f6ff"), 0.3, 0.3, 0.4)
