		K.cyl(self, 0.07, 0.07, GH, Vector3(sx * GW, GH * 0.5, GZ), post, 12)
	var bar := K.cyl(self, 0.07, 0.07, GW * 2.0, Vector3(0, GH, GZ), post, 12)
	bar.rotation.z = PI / 2
	net = K.box(self, Vector3(GW * 2.0, GH, 0.05), Vector3(0, GH * 0.5, GZ - 1.2), K.unlit(Color(1, 1, 1, 0.12)))
	for sx in [-1.0, 1.0]:
		K.box(self, Vector3(0.05, GH, 1.2), Vector3(sx * GW, GH * 0.5, GZ - 0.6), K.unlit(Color(1, 1, 1, 0.08)))
	K.box(self, Vector3(GW * 2.0, 0.05, 1.2), Vector3(0, GH, GZ - 0.6), K.unlit(Color(1, 1, 1, 0.08)))
