	mm.use_colors = true
	var pm := BoxMesh.new()
	pm.size = Vector3(0.45, 0.7, 0.35)
	mm.mesh = pm
	var people: Array = []
	for tier in 7:
		var z := GZ - 9.0 - tier * 1.6
		var y := 0.6 + tier * 1.1
		K.box(self, Vector3(70, 1.1, 1.6), Vector3(0, y - 0.55, z), stand_m)
		for k in 90:
			people.append(Transform3D(Basis(), Vector3(-34 + k * 0.76 + randf_range(-0.1, 0.1), y + 0.35, z)))
	mm.instance_count = people.size()
	for i in people.size():
		mm.set_instance_transform(i, people[i])
		var c: Color = G.NEON[randi() % 6] if randf() < 0.5 else Color(randf_range(0.5, 0.9), randf_range(0.4, 0.8), randf_range(0.4, 0.8))
		mm.set_instance_color(i, c)
