	add_child(crowd)
	K.box(self, Vector3(70, 0.3, 0.2), Vector3(0, 0.75, GZ - 8.2), K.neon(G.LIME, 2.5))
	for sx in [-1.0, 1.0]:
		var pole := K.cyl(self, 0.25, 0.35, 22, Vector3(sx * 22, 11, GZ - 8), K.mat(Color("2a2f40"), 0.8, 0.4), 10)
		pole.name = "Pole"
		K.box(self, Vector3(4.0, 2.0, 0.4), Vector3(sx * 22, 22, GZ - 8), K.neon(Color("eaf2ff"), 6.0))
		var sl := SpotLight3D.new()
		sl.position = Vector3(sx * 20, 21, GZ - 6)
		sl.look_at_from_position(sl.position, Vector3(0, 0, GZ + 2), Vector3.UP)
		sl.spot_angle = 30
		sl.spot_range = 50
		sl.light_energy = 3.0
		add_child(sl)
	# ball
	ball = Node3D.new()
	add_child(ball)
	K.sphere(ball, 0.22, Vector3.ZERO, K.mat(Color("f4f6ff"), 0.0, 0.4), 20)
	for k in 6:
		var d := Vector3(randf_range(-1, 1), randf_range(-1, 1), randf_range(-1, 1)).normalized()
		K.sphere(ball, 0.07, d * 0.18, K.mat(Color("15161c"), 0.0, 0.5), 8)
	ball.position = from
	# robot keeper
	keeper = Node3D.new()
	add_child(keeper)
	var km := K.mat(Color("9aa1b6"), 0.4, 0.35)
	K.box(keeper, Vector3(0.9, 1.0, 0.5), Vector3(0, 1.1, 0), km)
	K.box(keeper, Vector3(0.6, 0.5, 0.45), Vector3(0, 1.85, 0), km)
	K.box(keeper, Vector3(0.5, 0.1, 0.05), Vector3(0, 1.88, 0.23), K.neon(G.RED, 5.0))
	for sx in [-1.0, 1.0]:
		K.box(keeper, Vector3(0.22, 0.6, 0.3), Vector3(sx * 0.25, 0.3, 0), K.mat(Color("5a6072"), 0.4, 0.4))
