	kl.position = Vector3(0, 2.0, 1.5)
	kl.light_energy = 1.5
	kl.omni_range = 4.0
	keeper.add_child(kl)


func kspeed() -> float:
	return 1.4 + lvl * 0.5


func reach() -> float:
	return 1.25


func tick(dt: float) -> void:
	if not shot:
		kx = sin(t * kspeed()) * (GW - 0.9)
	else:
		st += dt
		var f := minf(st / flight, 1.0)
		var dv := 3.4 + lvl * 0.9
		kx = move_toward(kx, to.x, dv * dt)
		if not saved:
			var p := from.lerp(to, f)
			p.y += sin(f * PI) * 0.6
			ball.position = p
			ball.rotate_x(-dt * 20.0)
			if f >= 1.0 and result == 0:
				if absf(to.x - kx) < reach() and to.y < 2.3:
					saved = true
					G.play("clank")
					K.sparks(self, to, G.YELLOW, 16, 5.0, 0.6)
					lose("SAVED!")
				else:
					net_shake = 1.0
					G.play("cheer")
					G.play("win", 1.0, -6.0)
					K.sparks(self, to + Vector3(0, 0, -0.6), G.LIME, 30, 7.0)
					win("GOAL!")
		else:
			ball.position += Vector3(sign(ball.position.x - kx) * 3.0, 2.0, 6.0) * dt
	keeper.position.x = kx
	keeper.rotation.z = clampf((to.x - kx) * -0.3, -0.6, 0.6) if shot else 0.0
	net_shake = maxf(0.0, net_shake - dt * 2.0)
	net.position.z = GZ - 1.2 - sin(net_shake * 20.0) * net_shake * 0.3


func down(p: Vector2, _i: int) -> void:
	if shot or result != 0:
		return
	var g := plane_z(p, GZ)
	to = Vector3(clampf(g.x, -GW + 0.3, GW - 0.3), clampf(g.y, 0.3, GH - 0.25), GZ)
	shot = true
	G.play("kick")
	G.play("whoosh", 1.3, -6.0)


func auto(_dt: float) -> void:
	if shot:
		return
	var dv := 3.4 + lvl * 0.9
	for side in [-1.0, 1.0]:
		var tx: float = side * (GW - 0.35)
		if absf(tx - kx) > reach() + dv * flight + 0.2:
			down(spos(Vector3(tx, 1.0, GZ)), 0)
			return


func paint2d(ci: CanvasItem) -> void:
	if not shot and result == 0:
		var a := spos(Vector3(-GW, GH, GZ))
		var b := spos(Vector3(GW, 0, GZ))
		var r := Rect2(a, b - a)
		ci.draw_rect(r, Color(G.LIME, 0.35 + 0.25 * sin(t * 6.0)), false, 3 * U)

