	K.box(self, Vector3(9.2, 0.1, 0.6), Vector3(0, -0.15, -0.5), K.neon(G.LIME, 3.0))
	for k in 4:
		var c := Vector3((k % 2 - 0.5) * 3.2, 4.2 - (k / 2) * 2.6, 0)
		var frame := K.box(self, Vector3(2.8, 2.2, 0.3), c, K.mat(Color("0d1015"), 0.6, 0.3))
		frame.name = "Frame%d" % k
		var m := StandardMaterial3D.new()
		m.albedo_color = COLS[k].darkened(0.75)
		m.emission_enabled = true
		m.emission = COLS[k]
		m.emission_energy_multiplier = 0.25
		K.box(self, Vector3(2.5, 1.9, 0.1), c + Vector3(0, 0, 0.18), m)
		var sym := Node3D.new()
		add_child(sym)
		sym.position = c + Vector3(0, 0, 0.32)
		var sm := K.neon(COLS[k], 1.5)
		match k:
			0:
				K.prism(sym, Vector3(0.9, 0.8, 0.1), Vector3.ZERO, sm)
			1:
				K.sphere(sym, 0.42, Vector3.ZERO, sm, 16).scale = Vector3(1, 1, 0.25)
			2:
				K.box(sym, Vector3(0.75, 0.75, 0.1), Vector3.ZERO, sm).rotation.z = PI / 4
			3:
				K.torus(sym, 0.28, 0.45, Vector3.ZERO, sm, 24).rotation.x = PI / 2
		var l := OmniLight3D.new()
		l.position = c + Vector3(0, 0, 1.4)
		l.light_color = COLS[k]
		l.light_energy = 0.0
		l.omni_range = 4.0
		add_child(l)
		panels.append({c = c, m = m, l = l})
	var n := 2 + lvl
	for i in n:
		var k := randi() % 4
		while seq.size() > 0 and k == seq[seq.size() - 1] and randf() < 0.6:
			k = randi() % 4
		seq.append(k)
	step_len = 0.62 - lvl * 0.06
	dur = 0.5 + n * step_len + 2.4 + n * 0.55


func flash(k: int, t_len := 0.3) -> void:
	lit = k
	lit_t = t_len
	G.play("tone%d" % k)


func tick(dt: float) -> void:
	lit_t -= dt
	if lit_t <= 0.0:
		lit = -1
	for k in panels.size():
		var on := k == lit
		(panels[k].m as StandardMaterial3D).emission_energy_multiplier = 3.5 if on else 0.25
		(panels[k].l as OmniLight3D).light_energy = 3.0 if on else 0.0
	if phase == "show":
		show_t += dt
		var idx := int(floor((show_t - 0.5) / step_len))
		if show_t >= 0.5 and idx < seq.size() and idx > shown:
			shown = idx
			flash(seq[idx], step_len * 0.7)
		if show_t >= 0.5 + seq.size() * step_len + 0.1:
			phase = "input"
			G.play("beep", 1.2, -6.0)


func down(p: Vector2, _i: int) -> void:
	if phase != "input" or result != 0:
		return
	var best := -1
	var bd := 1.5
	for k in panels.size():
		var d := ray_dist(p, panels[k].c)
		if d < bd:
			bd = d
			best = k
	if best < 0:
		return
	flash(best, 0.25)
	if best == seq[pos]:
		pos += 1
		if pos >= seq.size():
			phase = "done"
			K.sparks(self, Vector3(0, 3, 0.5), G.LIME, 30, 7.0)
			win("ACCESS GRANTED")
	else:
		phase = "done"
		G.play("zap")
		shake(0.5)
		lose("ACCESS DENIED")


func auto(_dt: float) -> void:
	if phase == "input" and int(t * 60) % 14 == 0:
		down(spos(panels[seq[pos]].c), 0)


func paint2d(ci: CanvasItem) -> void:
	var s := "WATCH..." if phase == "show" else ("REPEAT IT!" if phase == "input" else "")
	if s != "":
		G.txt(ci, Vector2(W * 0.5, 140 * U), s, int(36 * U), G.LIME, 0, G.font_title, HORIZONTAL_ALIGNMENT_CENTER, G.INK, 1.0)
	var n := seq.size()
	for i in n:
		var c := Vector2(W * 0.5 + (i - (n - 1) * 0.5) * 40 * U, 186 * U)
		var filled := i < pos
		ci.draw_circle(c, 11 * U, G.LIME if filled else Color(1, 1, 1, 0.2), true, -1.0, true)

