extends "res://scripts/micro3d.gd"

var drone: Node3D
var y := 0.0
var vy := 0.0
var walls: Array = []
var pillars: Array = []
var sp := 20.0
var grid: MeshInstance3D
var dead := false
const BASE := 0.9


func setup() -> void:
	word = "JUMP!"
	hint = "Tap to jump over the laser walls!"
	dur = 5.0
	survive = true
	accent = G.MAGENTA
	world("sunset")
	place_cam(Vector3(2.8, 2.6, 5.2), Vector3(0, 1.1, -5.0), 60)
	sp = 18.0 + lvl * 4.0
	grid = K.ground(self, 240.0, G.MAGENTA, Color(0.04, 0.015, 0.05), 2.0, 2.4)
	(grid.material_override as ShaderMaterial).set_shader_parameter("scroll", Vector2(0, sp / 2.0))
	K.box(self, Vector3(4.2, 0.12, 240), Vector3(0, 0.02, -100), K.mat(Color("15121f"), 0.7, 0.25))
	for sx in [-1.0, 1.0]:
		K.box(self, Vector3(0.12, 0.16, 240), Vector3(sx * 2.15, 0.1, -100), K.neon(G.CYAN, 4.0))
	for i in 14:
		var side := -1.0 if i % 2 == 0 else 1.0
		var h := randf_range(4.0, 12.0)
		var p := K.box(self, Vector3(1.2, h, 1.2), Vector3(side * randf_range(6.0, 9.0), h * 0.5, -i * 9.0), K.mat(Color("1b1726"), 0.8, 0.3))
		K.box(p, Vector3(1.25, 0.15, 1.25), Vector3(0, h * 0.5 - 0.3, 0), K.neon(G.MAGENTA if i % 3 else G.YELLOW, 4.0))
		pillars.append(p)
	drone = K.drone(self, G.CYAN)
	var n := 2 if lvl < 3 else 3
	var z := -40.0
	for i in n:
		var h := randf_range(0.8, 1.15 + lvl * 0.12)
		walls.append(make_wall(z, h))
		z -= sp * randf_range(1.35, 1.6)


func make_wall(z: float, h: float) -> Dictionary:
	var n := Node3D.new()
	add_child(n)
	n.position = Vector3(0, 0, z)
	var post := K.mat(Color("2a2638"), 0.8, 0.3)
	for sx in [-1.0, 1.0]:
		K.box(n, Vector3(0.3, h + 0.5, 0.3), Vector3(sx * 2.25, (h + 0.5) * 0.5, 0), post)
		K.sphere(n, 0.16, Vector3(sx * 2.25, h + 0.55, 0), K.neon(G.RED, 6.0), 10)
	var bars := int(h / 0.32)
	for k in bars:
		var b := K.cyl(n, 0.045, 0.045, 4.4, Vector3(0, 0.3 + k * 0.32, 0), K.neon(G.RED, 6.0), 8)
		b.rotation.z = PI / 2
	K.box(n, Vector3(4.4, h, 0.02), Vector3(0, h * 0.5 + 0.1, 0), K.unlit(Color(1.0, 0.1, 0.2, 0.12), true))
	return {n = n, h = h, done = false}


func tick(dt: float) -> void:
	vy -= 22.0 * dt
	y += vy * dt
	if y < 0.0:
		y = 0.0
		vy = 0.0
	if not dead:
		drone.position = Vector3(0, BASE + y + sin(t * 4.0) * 0.05, 0)
		drone.rotation.x = clampf(vy * 0.04, -0.3, 0.3)
		K.spin_rotors(drone, dt)
	for w in walls:
		var n: Node3D = w.n
		n.position.z += sp * dt
		if not dead and absf(n.position.z) < 0.7 and y < w.h - 0.05:
			dead = true
			boom(drone.position, 1.2, G.CYAN, Color("1c1f2e"))
			drone.visible = false
			lose("ZAPPED!")
		if not w.done and n.position.z > 0.8 and not dead:
			w.done = true
			fx.text(spos(drone.position) - Vector2(0, 80 * U), "NICE!", G.LIME, 44 * U)
			G.play("xp", 1.2, -4.0)
	for p in pillars:
		p.position.z += sp * dt
		if p.position.z > 12.0:
			p.position.z -= 126.0


func down(_p: Vector2, _i: int) -> void:
	if y <= 0.001 and not dead:
		vy = 9.0
		G.play("jump")


func auto(_dt: float) -> void:
	for w in walls:
		var z: float = (w.n as Node3D).position.z
		if z < 0.0:
			var arrive := -z / sp
			if arrive < 0.4 and arrive > 0.3:
				down(Vector2.ZERO, 0)
			return

