extends "res://scripts/micro3d.gd"

var items: Array = []
var got := 0


func setup() -> void:
	word = "SMASH!"
	hint = "Tap to blow up all the boring gray junk!"
	dur = 5.0
	accent = G.ORANGE
	world("night")
	place_cam(Vector3(0, 6.6, 6.4), Vector3(0, 0.0, -1.9), 54)
	var key := OmniLight3D.new()
	key.position = Vector3(0, 6, 3)
	key.light_color = Color("ffe2c4")
	key.light_energy = 2.5
	key.omni_range = 16.0
	add_child(key)
	K.ground(self, 160.0, G.ORANGE, Color(0.03, 0.022, 0.04), 2.5, 1.4, -6.0)
	K.city(self, Vector3(0, -6, 0), 26.0, 90.0, 140, 11, 4.0, 30.0)
	K.box(self, Vector3(17, 0.5, 10), Vector3(0, -0.25, -0.5), K.mat(Color("22242f"), 0.5, 0.55))
	for sx in [-1.0, 1.0]:
		K.box(self, Vector3(0.12, 0.1, 10), Vector3(sx * 8.5, 0.03, -0.5), K.neon(G.ORANGE, 3.5))
	K.box(self, Vector3(17, 0.1, 0.12), Vector3(0, 0.03, 4.5), K.neon(G.ORANGE, 3.5))
	var n := 3 + lvl
	var spots: Array[Vector3] = []
	var tries := 0
	while spots.size() < n and tries < 400:
		tries += 1
		var p := Vector3(randf_range(-5.4, 5.4), 0, randf_range(-4.2, 1.6))
		var ok := true
		for q in spots:
			if q.distance_to(p) < 2.5:
				ok = false
				break
		if ok:
			spots.append(p)
	for i in spots.size():
		var node := make_item(i % 4)
		node.position = spots[i]
		node.rotation.y = randf_range(-0.5, 0.5)
		node.scale = Vector3.ONE * 1.3
		var hover := lvl >= 2 and i % 2 == 1
		items.append({n = node, base = spots[i], alive = true, hover = hover, ph = randf() * TAU})


func make_item(kind: int) -> Node3D:
	var root := Node3D.new()
	add_child(root)
	var gray := K.mat(Color("9aa0b2"), 0.5, 0.45)
	var dark := K.mat(Color("5a6070"), 0.6, 0.45)
	var hz := K.neon(G.ORANGE, 2.0)
	match kind:
		0:
			K.box(root, Vector3(1.3, 1.3, 1.3), Vector3(0, 0.65, 0), gray)
			for y in [0.15, 1.15]:
				K.box(root, Vector3(1.36, 0.12, 1.36), Vector3(0, y, 0), dark)
			K.box(root, Vector3(0.12, 1.32, 1.36), Vector3(0, 0.65, 0), dark)
			K.box(root, Vector3(0.5, 0.08, 1.38), Vector3(0.4, 1.0, 0), hz)
		1:
			K.box(root, Vector3(1.6, 1.15, 1.0), Vector3(0, 0.75, 0), gray)
			K.box(root, Vector3(1.25, 0.85, 0.05), Vector3(0, 0.78, 0.5), K.mat(Color("8a93a8"), 0.2, 0.25, 0.25))
			for sx in [-1.0, 1.0]:
				var a := K.cyl(root, 0.02, 0.02, 0.8, Vector3(sx * 0.25, 1.6, 0), dark, 6)
				a.rotation.z = -sx * 0.5
			K.box(root, Vector3(1.2, 0.2, 0.6), Vector3(0, 0.1, 0), dark)
			K.box(root, Vector3(0.2, 0.06, 0.04), Vector3(0.6, 0.3, 0.5), hz)
		2:
			K.cyl(root, 0.6, 0.6, 1.4, Vector3(0, 0.7, 0), gray, 20)
			for y in [0.3, 1.1]:
				K.cyl(root, 0.63, 0.63, 0.1, Vector3(0, y, 0), dark, 20)
			K.cyl(root, 0.62, 0.62, 0.12, Vector3(0, 0.7, 0), hz, 20)
		3:
			K.box(root, Vector3(1.3, 1.4, 1.2), Vector3(0, 0.7, 0), dark)
			var dial := K.cyl(root, 0.25, 0.25, 0.08, Vector3(0.15, 0.8, 0.62), gray, 16)
			dial.rotation.x = PI / 2
			K.box(root, Vector3(0.08, 0.5, 0.06), Vector3(-0.35, 0.7, 0.62), gray)
			K.box(root, Vector3(1.32, 0.08, 0.04), Vector3(0, 1.3, 0.6), hz)
	return root


func tick(dt: float) -> void:
	for it in items:
		if it.alive and it.hover:
			var n: Node3D = it.n
			n.position = it.base + Vector3(sin(t * 1.4 + it.ph) * 1.2, 0.8 + sin(t * 2.3 + it.ph) * 0.35, 0)
			n.rotation.y += dt * 0.8


func center(it: Dictionary) -> Vector3:
	return (it.n as Node3D).position + Vector3(0, 0.9, 0)


func down(p: Vector2, _i: int) -> void:
	if result != 0:
		return
	var best = null
	var bd := 1.25
	for it in items:
		if it.alive:
			var d := ray_dist(p, center(it))
			if d < bd:
				bd = d
				best = it
	if best == null:
		return
	best.alive = false
	var c := center(best)
	(best.n as Node3D).queue_free()
	boom(c, 1.0, Color("ff7a1a"), Color("6b7080"), "boom_s")
	got += 1
	fx.text(spos(c) - Vector2(0, 50 * U), "BOOM!", G.YELLOW, 50 * U)
	if got >= items.size():
		win("WRECKED!")


func auto(_dt: float) -> void:
	if int(t * 60) % 14 == 0:
		for it in items:
			if it.alive:
				down(spos(center(it)), 0)
				return


func paint2d(ci: CanvasItem) -> void:
	G.txt(ci, Vector2(W - 40 * U, 150 * U), "%d / %d" % [got, items.size()], int(44 * U), G.WHITE, int(6 * U), null, HORIZONTAL_ALIGNMENT_RIGHT)
	for it in items:
		if it.alive:
			var c := spos(center(it))
			G.brackets(ci, c, 46 * U, Color(G.ORANGE, 0.8), 3 * U, t * 1.5)

