extends "res://scripts/micro3d.gd"

var tower: Array = []   # {pos: Vector3, size: Vector3}
var mover: MeshInstance3D
var msize := Vector3(3, 0.6, 3)
var axis := 0
var mt := 0.0
var need := 3
var placed := 0
var falling: Array = []
var speed := 3.5
var cam_y := 0.0
const AMP := 4.2


func setup() -> void:
	word = "STACK!"
	hint = "Tap to drop - stack them high!"
	accent = G.CYAN
	need = 2 + lvl
	dur = 4.5 + lvl * 1.1
	speed = 3.6 + lvl * 0.7
	world("void", true, 30.0)
	place_cam(Vector3(8.5, 7.0, 8.5), Vector3(0, 1.4, 0), 45)
	K.ground(self, 160.0, G.CYAN, Color(0.01, 0.02, 0.03), 2.0, 1.6, -0.5)
	var base := K.box(self, Vector3(3, 1.0, 3), Vector3(0, -0.2, 0), K.mat(Color("1b2030"), 0.8, 0.3))
	base.name = "Base"
	K.box(self, Vector3(3.1, 0.08, 3.1), Vector3(0, 0.3, 0), K.neon(G.CYAN, 3.0))
	tower.append({pos = Vector3(0, 0, 0), size = Vector3(3, 0.6, 3)})
	for i in 10:
		var a := i * TAU / 10.0
		var p := K.box(self, Vector3(0.4, randf_range(3, 9), 0.4), Vector3(cos(a) * 14, 2, sin(a) * 14), K.mat(Color("101521"), 0.8, 0.3))
		K.box(p, Vector3(0.45, 0.1, 0.45), Vector3(0, p.mesh.size.y * 0.5, 0), K.neon(G.NEON[i % 6], 4.0))
	new_mover()


func top() -> Dictionary:
	return tower[tower.size() - 1]


func level_y(i: int) -> float:
	return 0.6 + i * 0.6


func new_mover() -> void:
	axis = placed % 2
	var tp := top()
	msize = tp.size
	var col: Color = G.NEON[(placed + 1) % 6]
	mover = K.box(self, msize, Vector3.ZERO, K.mat(col.darkened(0.35), 0.3, 0.35))
	K.box(mover, Vector3(msize.x + 0.04, 0.05, msize.z + 0.04), Vector3(0, msize.y * 0.5, 0), K.neon(col, 1.3))
	mt = -PI / 2 if randf() < 0.5 else PI / 2
	update_mover()


func update_mover() -> void:
	var tp := top()
	var off := sin(mt) * AMP
	var p := Vector3(tp.pos.x, level_y(tower.size() - 1) + 0.3, tp.pos.z)
	if axis == 0:
		p.x = off
	else:
		p.z = off
	mover.position = p


func tick(dt: float) -> void:
	if mover and result == 0:
		mt += dt * speed / AMP
		update_mover()
	for f in falling:
		f.v.y -= 20.0 * dt
		(f.n as Node3D).position += f.v * dt
		(f.n as Node3D).rotation.z += f.r * dt
	var want := level_y(tower.size()) * 0.9
	cam_y = lerpf(cam_y, want, minf(1.0, dt * 4.0))
	cam.position = Vector3(8.5, 7.0 + cam_y, 8.5)
	cam.look_at(Vector3(0, 1.4 + cam_y, 0), Vector3.UP)


func down(_p: Vector2, _i: int) -> void:
	if result != 0 or mover == null:
		return
	var tp := top()
	var mp := mover.position
	var off: float = (mp.x - tp.pos.x) if axis == 0 else (mp.z - tp.pos.z)
	var w: float = tp.size.x if axis == 0 else tp.size.z
	if absf(off) < 0.18:
		off = 0.0
		if axis == 0:
			mp.x = tp.pos.x
		else:
			mp.z = tp.pos.z
		fx.text(spos(mp) - Vector2(0, 60 * U), "PERFECT!", G.YELLOW, 44 * U)
		K.flash_ring(self, mp, G.YELLOW, 2.0)
		G.play("xp", 1.3)
	var overlap := w - absf(off)
	if overlap <= 0.05:
		falling.append({n = mover, v = Vector3(0, 0, 0), r = 2.0})
		mover = null
		G.play("thud")
		lose("MISSED!")
		return
	var ns: Vector3 = tp.size
	var np := mp
	if axis == 0:
		ns.x = overlap
		np.x = tp.pos.x + off * 0.5
	else:
		ns.z = overlap
		np.z = tp.pos.z + off * 0.5
	# chop off the overhang as a falling piece
	if absf(off) > 0.0:
		var cs: Vector3 = tp.size
		var cp := mp
		if axis == 0:
			cs.x = absf(off)
			cp.x = np.x + sign(off) * (overlap + absf(off)) * 0.5
		else:
			cs.z = absf(off)
			cp.z = np.z + sign(off) * (overlap + absf(off)) * 0.5
		var chunk := K.box(self, cs, cp, mover.material_override)
		falling.append({n = chunk, v = Vector3(sign(off) * 2.0 if axis == 0 else 0.0, 1.0, sign(off) * 2.0 if axis == 1 else 0.0), r = sign(off) * 3.0})
	mover.queue_free()
	var col: Color = G.NEON[(placed + 1) % 6]
	var blk := K.box(self, ns, Vector3(np.x, level_y(tower.size() - 1) + 0.3, np.z), K.mat(col.darkened(0.35), 0.3, 0.35))
	K.box(blk, Vector3(ns.x + 0.04, 0.05, ns.z + 0.04), Vector3(0, ns.y * 0.5, 0), K.neon(col, 1.3))
	tower.append({pos = Vector3(np.x, 0, np.z), size = ns})
	placed += 1
	G.play("thud", 1.2)
	shake(0.15)
	if placed >= need:
		mover = null
		K.sparks(self, blk.position + Vector3(0, 0.4, 0), col, 30, 7.0)
		win("TOWER UP!")
	else:
		new_mover()


func auto(_dt: float) -> void:
	if mover == null:
		return
	var tp := top()
	var off: float = (mover.position.x - tp.pos.x) if axis == 0 else (mover.position.z - tp.pos.z)
	if absf(off) < 0.12:
		down(Vector2.ZERO, 0)


func paint2d(ci: CanvasItem) -> void:
	G.txt(ci, Vector2(W - 40 * U, 150 * U), "%d / %d" % [placed, need], int(44 * U), G.WHITE, int(6 * U), null, HORIZONTAL_ALIGNMENT_RIGHT)

